struct Entry { word: Str, count: Int }

fn add_word(counts: HashMap<Str, Int>, w: Str) -> HashMap<Str, Int> {
  let mut m = counts;
  let c = m.get(w).unwrap_or(0);
  m.insert(w, c + 1);
  m
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let data = input.read("text.txt")?;
  let mut counts: HashMap<Str, Int> = HashMap::new();
  let mut cur: Bytes = "".to_bytes();
  for b in data {
    if b >= 65 && b <= 90 {
      cur.push(b + 32);
    } else if b >= 97 && b <= 122 {
      cur.push(b);
    } else if cur.len() > 0 {
      counts = add_word(counts, cur.to_str());
      cur = "".to_bytes();
    }
  }
  if cur.len() > 0 {
    counts = add_word(counts, cur.to_str());
  }
  let mut entries: List<Entry> = [];
  for k in counts.keys() {
    entries.push(Entry { word: k, count: counts.get(k).unwrap_or(0) });
  }
  entries.sort_by(|a, b| a.count > b.count || (a.count == b.count && a.word < b.word));
  let n = entries.len().min(5);
  let mut lines: List<Str> = [];
  for i in 0..n {
    lines.push(entries[i].word + " " + entries[i].count.to_str());
  }
  Ok(lines.join("\n"))
}

struct Agg { name: Str, qty: Int, rev: Int }

fn fmt_cents(c: Int) -> Str {
  let mut sign = "";
  let mut v = c;
  if v < 0 { sign = "-"; v = 0 - v; }
  let d = v / 100;
  let r = v % 100;
  let mut rs = r.to_str();
  if r < 10 { rs = "0" + rs; }
  sign + d.to_str() + "." + rs
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("sales.csv")?.to_str();
  let mut aggs: Map<Str, Agg> = Map::new();
  let mut skipped = 0;
  let mut first = true;
  for line in text.lines() {
    if first { first = false; continue; }
    if line.trim() == "" { continue; }
    let parts = line.split(",");
    if parts.len() != 5 { skipped += 1; continue; }
    let region = parts[1].trim();
    let Some(q) = parts[3].trim().parse_int() else { skipped += 1; continue; };
    let Some(u) = parts[4].trim().parse_int() else { skipped += 1; continue; };
    let cur = aggs.get(region).unwrap_or(Agg { name: region, qty: 0, rev: 0 });
    aggs.insert(region, Agg { name: region, qty: cur.qty + q, rev: cur.rev + q * u });
  }
  let mut list: List<Agg> = [];
  for k in aggs.keys() {
    let Some(a) = aggs.get(k) else { continue; };
    list.push(a);
  }
  list.sort_by(|a: Agg, b: Agg| a.rev > b.rev || (a.rev == b.rev && a.name < b.name));
  let mut out: List<Str> = [];
  for a in list {
    out.push(a.name + " " + a.qty.to_str() + " " + fmt_cents(a.rev));
  }
  out.push("skipped " + skipped.to_str());
  Ok(out.join("\n"))
}

struct Entry { ip: Str, path: Str, status: Int, size: Int }

fn words(s: Str) -> List<Str> {
  s.split(" ").filter(|w| w != "")
}

fn parse_line(line: Str) -> Option<Entry> {
  let parts = line.split("\"");
  if parts.len() != 3 { return None; }
  let pre = words(parts[0]);
  if pre.len() < 4 { return None; }
  if !pre[3].starts_with("[") { return None; }
  if !pre[pre.len() - 1].ends_with("]") { return None; }
  let req = words(parts[1]);
  if req.len() != 3 { return None; }
  let post = words(parts[2]);
  if post.len() != 2 { return None; }
  let status = post[0].parse_int()?;
  if status < 100 || status > 599 { return None; }
  let mut size = 0;
  if post[1] != "-" {
    size = post[1].parse_int()?;
    if size < 0 { return None; }
  }
  let mut path = req[1];
  if let Some(i) = path.find("?") {
    path = path.slice(0, i);
  }
  Some(Entry { ip: pre[0], path: path, status: status, size: size })
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("access.log")?.to_str();
  let mut statuses: Map<Int, Int> = Map::new();
  let mut paths: Map<Str, Int> = Map::new();
  let mut errs: Map<Str, Int> = Map::new();
  let mut total = 0;
  for line in text.lines() {
    let Some(e) = parse_line(line) else { continue; };
    statuses.insert(e.status, statuses.get(e.status).unwrap_or(0) + 1);
    paths.insert(e.path, paths.get(e.path).unwrap_or(0) + 1);
    total = total + e.size;
    if e.status >= 500 && e.status <= 599 {
      errs.insert(e.ip, errs.get(e.ip).unwrap_or(0) + 1);
    }
  }
  let mut out: List<Str> = [];
  for s in statuses.keys() {
    out.push(s.to_str() + " " + statuses.get(s).unwrap_or(0).to_str());
  }
  out.push("bytes " + total.to_str());
  let mut best = "";
  let mut best_n = 0;
  for p in paths.keys() {
    let n = paths.get(p).unwrap_or(0);
    if n > best_n {
      best_n = n;
      best = p;
    }
  }
  if best_n > 0 {
    out.push("top " + best + " " + best_n.to_str());
  }
  let counts = errs;
  let mut ips = errs.keys();
  ips.sort_by(|a, b| {
    let ca = counts.get(a).unwrap_or(0);
    let cb = counts.get(b).unwrap_or(0);
    if ca != cb { ca > cb } else { a < b }
  });
  for ip in ips {
    out.push("errors " + ip + " " + errs.get(ip).unwrap_or(0).to_str());
  }
  Ok(out.join("\n"))
}

fn order_total(o: Json) -> Int {
  let items = o.get("items").and_then(|j| j.as_list()).unwrap_or([]);
  let mut t = 0;
  for it in items {
    let q = it.get("qty").and_then(|j| j.as_int()).unwrap_or(0);
    let p = it.get("price_cents").and_then(|j| j.as_int()).unwrap_or(0);
    t = t + q * p;
  }
  t
}

fn main(input: Dir) -> Result<Str, Str> {
  let bytes = input.read("orders.json").map_err(|e| "cannot read orders.json")?;
  let doc = bytes.to_str().parse_json()?;
  let orders = doc.as_list().ok_or("orders.json is not an array")?;

  let mut counts: Map<Str, Int> = Map::new();
  let mut totals: Map<Str, Int> = Map::new();
  let mut ref_n = 0;
  let mut ref_t = 0;
  let mut pend_n = 0;

  for o in orders {
    let status = o.get("status").and_then(|j| j.as_str()).unwrap_or("");
    let t = order_total(o);
    if status == "paid" {
      let c = o.get("customer").and_then(|j| j.as_str()).unwrap_or("");
      let n = counts.get(c).unwrap_or(0);
      counts.insert(c, n + 1);
      let s = totals.get(c).unwrap_or(0);
      totals.insert(c, s + t);
    } else if status == "refunded" {
      ref_n = ref_n + 1;
      ref_t = ref_t + t;
    } else if status == "pending" {
      pend_n = pend_n + 1;
    }
  }

  let mut lines: List<Str> = [];
  for c in counts.keys() {
    let n = counts.get(c).unwrap_or(0);
    let s = totals.get(c).unwrap_or(0);
    lines.push(c + " " + n.to_str() + " " + s.to_str());
  }
  lines.push("refunded " + ref_n.to_str() + " " + ref_t.to_str());
  lines.push("pending " + pend_n.to_str());
  Ok(lines.join("\n"))
}

fn normalize(line: Str) -> Option<Str> {
  let parts = line.split("@");
  if parts.len() != 2 { return None; }
  let mut local = parts[0];
  let domain = parts[1];
  if local.len() == 0 { return None; }
  if domain.len() == 0 { return None; }
  if !domain.contains(".") { return None; }
  if domain.starts_with(".") || domain.ends_with(".") { return None; }
  if domain == "gmail.com" {
    if let Some(i) = local.find("+") {
      local = local.slice(0, i);
    }
    local = local.replace(".", "");
  }
  Some(local + "@" + domain)
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("emails.txt")?.to_str();
  let mut seen: Map<Str, Bool> = Map::new();
  let mut invalid = 0;
  for raw in text.lines() {
    let line = raw.trim().to_lowercase();
    if line.len() == 0 { continue; }
    match normalize(line) {
      Some(addr) => { seen.insert(addr, true); }
      None => { invalid = invalid + 1; }
    }
  }
  let mut out = "";
  for k in seen.keys() {
    out = out + k + "\n";
  }
  out = out + "invalid " + invalid.to_str();
  Ok(out)
}

fn to_roman(n: Int) -> Str {
  let vals = [1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1];
  let syms = ["M", "CM", "D", "CD", "C", "XC", "L", "XL", "X", "IX", "V", "IV", "I"];
  let mut out = "";
  let mut rest = n;
  for i in 0..vals.len() {
    while rest >= vals[i] {
      out = out + syms[i];
      rest = rest - vals[i];
    }
  }
  out
}

fn char_val(c: Str) -> Option<Int> {
  match c {
    "I" => Some(1),
    "V" => Some(5),
    "X" => Some(10),
    "L" => Some(50),
    "C" => Some(100),
    "D" => Some(500),
    "M" => Some(1000),
    _ => None,
  }
}

fn from_roman(s: Str) -> Option<Int> {
  if s.len() == 0 || s.len() > 15 { return None; }
  let mut vals: List<Int> = [];
  for c in s.chars() {
    vals.push(char_val(c)?);
  }
  let mut total = 0;
  for i in 0..vals.len() {
    if i + 1 < vals.len() && vals[i] < vals[i + 1] {
      total = total - vals[i];
    } else {
      total = total + vals[i];
    }
  }
  if total < 1 || total > 3999 { return None; }
  if to_roman(total) == s { Some(total) } else { None }
}

fn convert(v: Str) -> Str {
  if let Some(n) = v.parse_int() {
    if n >= 1 && n <= 3999 { return to_roman(n); }
    return "invalid";
  }
  match from_roman(v) {
    Some(n) => n.to_str(),
    None => "invalid",
  }
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("numbers.txt")?.to_str();
  let mut out: List<Str> = [];
  for line in text.lines() {
    let v = line.trim();
    if v.len() == 0 { continue; }
    out.push(v + " = " + convert(v));
  }
  Ok(out.join("\n"))
}

fn closer(b: Int) -> Str {
  if b == 40 { ")" } else if b == 91 { "]" } else { "}" }
}

fn check(line: Str) -> Str {
  let mut stack: List<Str> = [];
  let mut col = 0;
  for b in line.to_bytes() {
    col = col + 1;
    if b == 40 || b == 91 || b == 123 {
      stack.push(closer(b));
    } else if b == 41 || b == 93 || b == 125 {
      let found = if b == 41 { ")" } else if b == 93 { "]" } else { "}" };
      match stack.pop() {
        None => {
          return "col " + col.to_str() + ": unexpected " + found;
        }
        Some(exp) => {
          if exp != found {
            return "col " + col.to_str() + ": expected " + exp + ", found " + found;
          }
        }
      }
    }
  }
  match stack.pop() {
    None => "ok",
    Some(exp) => "unclosed " + exp,
  }
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("snippets.txt")?.to_str();
  let mut out: List<Str> = [];
  for line in text.lines() {
    out.push(check(line));
  }
  Ok(out.join("\n"))
}

fn rank(ts: List<Int>, p: Int) -> Int {
  let n = ts.len();
  let mut r = (p * n + 99) / 100;
  if r < 1 { r = 1; }
  if r > n { r = n; }
  ts[r - 1]
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("timings.log")?.to_str();
  let mut groups: Map<Str, Map<Str, List<Int>>> = Map::new();
  for raw in text.lines() {
    let line = raw.trim();
    let fields = line.split(" ").filter(|f| f != "");
    if fields.len() != 3 { continue; }
    let Some(ms) = fields[2].parse_int() else { continue; };
    let method = fields[0];
    let path = fields[1];
    let mut inner: Map<Str, List<Int>> = groups.get(method).unwrap_or(Map::new());
    let mut ts: List<Int> = inner.get(path).unwrap_or([]);
    ts.push(ms);
    inner.insert(path, ts);
    groups.insert(method, inner);
  }
  let mut out: List<Str> = [];
  for method in groups.keys() {
    let inner = groups.get(method).unwrap_or(Map::new());
    for path in inner.keys() {
      let mut ts: List<Int> = inner.get(path).unwrap_or([]);
      if ts.len() == 0 { continue; }
      ts.sort();
      let n = ts.len();
      out.push(method + " " + path + " count=" + n.to_str()
        + " p50=" + rank(ts, 50).to_str()
        + " p95=" + rank(ts, 95).to_str()
        + " max=" + ts[n - 1].to_str());
    }
  }
  Ok(out.join("\n"))
}

struct Edge { v: Int, w: Int }

fn words(line: Str) -> List<Str> {
  line.replace("\t", " ").split(" ").filter(|s| s.len() > 0)
}

fn dijkstra(adj: List<List<Edge>>, src: Int) -> List<Int> {
  let n = adj.len();
  let mut dist: List<Int> = [];
  for i in 0..n { dist.push(-1); }
  dist[src] = 0;
  let mut hd: List<Int> = [0];
  let mut hn: List<Int> = [src];
  while hd.len() > 0 {
    let d = hd[0];
    let u = hn[0];
    let ld = hd.pop().unwrap_or(0);
    let ln = hn.pop().unwrap_or(0);
    if hd.len() > 0 {
      hd[0] = ld;
      hn[0] = ln;
      let m = hd.len();
      let mut i = 0;
      loop {
        let l = 2 * i + 1;
        let r = l + 1;
        let mut s = i;
        if l < m && hd[l] < hd[s] { s = l; }
        if r < m && hd[r] < hd[s] { s = r; }
        if s == i { break; }
        let td = hd[s]; hd[s] = hd[i]; hd[i] = td;
        let tn = hn[s]; hn[s] = hn[i]; hn[i] = tn;
        i = s;
      }
    }
    if d > dist[u] { continue; }
    for e in adj[u] {
      let nd = d + e.w;
      if dist[e.v] == -1 || nd < dist[e.v] {
        dist[e.v] = nd;
        hd.push(nd);
        hn.push(e.v);
        let mut i = hd.len() - 1;
        while i > 0 {
          let p = (i - 1) / 2;
          if hd[p] <= hd[i] { break; }
          let td = hd[p]; hd[p] = hd[i]; hd[i] = td;
          let tn = hn[p]; hn[p] = hn[i]; hn[i] = tn;
          i = p;
        }
      }
    }
  }
  dist
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("routes.txt")?.to_str();
  let mut ids: HashMap<Str, Int> = HashMap::new();
  let mut names: List<Str> = [];
  let mut adj: List<List<Edge>> = [];
  let mut trips: List<List<Str>> = [];
  for raw in text.lines() {
    let line = raw.trim();
    if line.len() == 0 || line.starts_with("#") { continue; }
    let w = words(line);
    if w.len() == 4 && w[0] == "road" {
      let Some(c) = w[3].parse_int() else { continue; };
      let mut ends: List<Int> = [];
      for k in 1..3 {
        let name = w[k];
        let id = match ids.get(name) {
          Some(i) => i,
          None => {
            let i = names.len();
            ids.insert(name, i);
            names.push(name);
            let empty: List<Edge> = [];
            adj.push(empty);
            i
          }
        };
        ends.push(id);
      }
      let a = ends[0];
      let b = ends[1];
      adj[a].push(Edge { v: b, w: c });
      adj[b].push(Edge { v: a, w: c });
    } else if w.len() == 3 && w[0] == "trip" {
      trips.push([w[1], w[2]]);
    }
  }
  let mut out: List<Str> = [];
  for t in trips {
    let x = t[0];
    let y = t[1];
    if x == y { out.push(x + " 0"); continue; }
    let Some(s) = ids.get(x) else { out.push(x + " " + y + " unreachable"); continue; };
    let Some(g) = ids.get(y) else { out.push(x + " " + y + " unreachable"); continue; };
    let dx = dijkstra(adj, s);
    if dx[g] == -1 { out.push(x + " " + y + " unreachable"); continue; }
    let dy = dijkstra(adj, g);
    let total = dx[g];
    let mut path: List<Str> = [names[s]];
    let mut cur = s;
    while cur != g {
      let mut best = -1;
      for e in adj[cur] {
        if dx[cur] + e.w == dx[e.v] && dy[e.v] != -1 && dx[e.v] + dy[e.v] == total {
          if best == -1 || names[e.v] < names[best] { best = e.v; }
        }
      }
      if best == -1 { break; }
      cur = best;
      path.push(names[cur]);
    }
    out.push(path.join(" -> ") + " " + total.to_str());
  }
  Ok(out.join("\n"))
}

struct Line { path: Str, text: Str }

fn merge(base: Map<Str, Json>, ov: Map<Str, Json>) -> Map<Str, Json> {
  let mut out = base;
  for k in ov.keys() {
    let Some(v) = ov.get(k) else { continue; };
    match v {
      Json::Null => { out.remove(k); }
      Json::Obj(o) => {
        let mut b: Map<Str, Json> = Map::new();
        if let Some(Json::Obj(bo)) = out.get(k) { b = bo; }
        out.insert(k, Json::Obj(merge(b, o)));
      }
      other => { out.insert(k, other); }
    }
  }
  out
}

fn join(prefix: Str, k: Str) -> Str {
  if prefix == "" { k } else { prefix + "." + k }
}

fn flat(path: Str, j: Json, acc: List<Line>) -> List<Line> {
  let mut out = acc;
  match j {
    Json::Obj(m) => {
      if m.len() == 0 {
        out.push(Line { path: path, text: "{}" });
      } else {
        for k in m.keys() {
          let Some(v) = m.get(k) else { continue; };
          out = flat(join(path, k), v, out);
        }
      }
    }
    Json::Arr(xs) => {
      if xs.len() == 0 {
        out.push(Line { path: path, text: "[]" });
      } else {
        for i in 0..xs.len() {
          out = flat(join(path, i.to_str()), xs[i], out);
        }
      }
    }
    other => {
      out.push(Line { path: path, text: other.to_json() });
    }
  }
  out
}

fn load(d: Dir, name: Str) -> Result<Map<Str, Json>, Str> {
  let bytes = d.read(name).map_err(|e| "cannot read " + name)?;
  let j = bytes.to_str().parse_json()?;
  match j {
    Json::Obj(m) => Ok(m),
    _ => Err(name + " is not an object"),
  }
}

fn main(input: Dir) -> Result<Str, Str> {
  let base = load(input, "base.json")?;
  let ov = load(input, "override.json")?;
  let merged = merge(base, ov);
  let mut lines: List<Line> = [];
  for k in merged.keys() {
    let Some(v) = merged.get(k) else { continue; };
    lines = flat(k, v, lines);
  }
  lines.sort_by_key(|l| l.path);
  let mut out = "";
  for l in lines {
    out = out + l.path + "=" + l.text + "\n";
  }
  Ok(out)
}

fn main(input: Dir, out: Dir) -> Result<Str, IoErr> {
  let text = input.read("app.log")?.to_str();
  let mut err_out = "";
  let mut warn_out = "";
  let mut info_out = "";
  let mut ne = 0;
  let mut nw = 0;
  let mut ni = 0;
  let mut no = 0;
  for line in text.lines() {
    if line.trim().len() == 0 { continue; }
    let fields = line.split(" ").filter(|f| f.len() > 0);
    if fields.len() < 3 { no += 1; continue; }
    let level = fields[1].to_uppercase();
    if level == "ERROR" {
      err_out = err_out + line + "\n";
      ne += 1;
    } else if level == "WARN" || level == "WARNING" {
      warn_out = warn_out + line + "\n";
      nw += 1;
    } else if level == "INFO" {
      info_out = info_out + line + "\n";
      ni += 1;
    } else {
      no += 1;
    }
  }
  out.write("error.log", err_out.to_bytes())?;
  out.write("warn.log", warn_out.to_bytes())?;
  out.write("info.log", info_out.to_bytes())?;
  Ok("error " + ne.to_str() + "\nwarn " + nw.to_str() + "\ninfo " + ni.to_str() + "\nother " + no.to_str())
}

fn walk(d: Dir, dir: Str, acc: List<Str>) -> Result<List<Str>, IoErr> {
  let mut out = acc;
  let names = d.list(dir)?;
  for name in names {
    let base = if dir == "" { "" } else { dir + "/" };
    if let Some(sub) = name.strip_suffix("/") {
      out = walk(d, base + sub, out)?;
    } else {
      out.push(base + name);
    }
  }
  Ok(out)
}

fn count_lines(b: Bytes) -> Int {
  let mut n = 0;
  for c in b {
    if c == 10 { n = n + 1; }
  }
  if b.len() > 0 && b[b.len() - 1] != 10 { n = n + 1; }
  n
}

fn main(input: Dir, out: Dir) -> Result<Str, IoErr> {
  let empty: List<Str> = [];
  let mut paths = walk(input, "", empty)?;
  paths.sort();
  let mut csv = "path,bytes,lines\n";
  let mut total = 0;
  let mut files = 0;
  for p in paths {
    let data = input.read(p)?;
    let size = data.len();
    total = total + size;
    files = files + 1;
    csv = csv + p + "," + size.to_str() + "," + count_lines(data).to_str() + "\n";
  }
  out.create("index.csv", csv.to_bytes())?;
  Ok("files " + files.to_str() + " bytes " + total.to_str())
}

fn parse_csv(line: Str) -> List<Str> {
