fn normalize(name: Str) -> Str {
  let lower = name.to_lowercase();
  let mut out = "";
  let mut in_run = false;
  for c in lower.chars() {
    let ok = (c >= "a" && c <= "z") || (c >= "0" && c <= "9") || c == ".";
    if ok {
      out = out + c;
      in_run = false;
    } else {
      if !in_run {
        out = out + "-";
        in_run = true;
      }
    }
  }
  let mut s = out;
  loop {
    let Some(r) = s.strip_prefix("-") else { break; };
    s = r;
  }
  loop {
    let Some(r) = s.strip_suffix("-") else { break; };
    s = r;
  }
  s
}

fn main(input: Dir, out: Dir) -> Result<Str, IoErr> {
  let mut names = input.list("")?;
  names.sort();
  let mut taken: HashMap<Str, Bool> = HashMap::new();
  let mut lines: List<Str> = [];
  for name in names {
    if name.ends_with("/") { continue; }
    let n = normalize(name);
    if n == "" || n == "." || n == ".." || taken.get(n).is_some() {
      lines.push(name + " skipped");
      continue;
    }
    let data = input.read(name)?;
    out.create(n, data)?;
    taken.insert(n, true);
    lines.push(name + " -> " + n);
  }
  Ok(lines.join("\n"))
}

fn is_part(name: Str) -> Bool {
  let Some(rest) = name.strip_prefix("part-") else { return false; };
  let Some(mid) = rest.strip_suffix(".txt") else { return false; };
  if mid.len() != 4 { return false; }
  let digits = "0123456789";
  for c in mid.chars() {
    if !digits.contains(c) { return false; }
  }
  true
}

fn parse_part(text: Str) -> Option<List<Int>> {
  let mut vals: List<Int> = [];
  for line in text.lines() {
    let t = line.trim();
    if t.len() == 0 { continue; }
    let Some(n) = t.parse_int() else { return None; };
    vals.push(n);
  }
  Some(vals)
}

fn main(input: Dir, out: Dir) -> Result<Str, IoErr> {
  let names = input.list("")?;
  let mut parts = 0;
  let mut corrupt = 0;
  let mut seen: Map<Int, Bool> = Map::new();
  for name in names {
    if !is_part(name) { continue; }
    parts += 1;
    let bytes = input.read(name)?;
    let text = bytes.to_str();
    match parse_part(text) {
      Some(vals) => {
        for v in vals { seen.insert(v, true); }
      }
      None => { corrupt += 1; }
    }
  }
  let keys = seen.keys();
  let mut body = "";
  for k in keys {
    body = body + k.to_str() + "\n";
  }
  out.create("merged.txt", body.to_bytes())?;
  Ok("parts " + parts.to_str() + " corrupt " + corrupt.to_str() + " values " + keys.len().to_str())
}

fn main(src: Dir, dst: Dir) -> Result<Str, IoErr> {
  let src_names = src.list("")?;
  let dst_names = dst.list("")?;
  let mut lines: List<Str> = [];
  let mut files: List<Str> = [];
  for n in src_names {
    if n.ends_with("/") { continue; }
    files.push(n);
  }
  files.sort();
  for name in files {
    let data = src.read(name)?;
    if dst_names.contains(name) {
      let existing = dst.read(name)?;
      if existing == data {
        lines.push("same " + name);
      } else {
        dst.write(name, data)?;
        lines.push("updated " + name);
      }
    } else {
      dst.write(name, data)?;
      lines.push("added " + name);
    }
  }
  let mut kept = 0;
  for n in dst_names {
    if n.ends_with("/") { continue; }
    if !files.contains(n) { kept += 1; }
  }
  lines.push("kept " + kept.to_str());
  Ok(lines.join("\n"))
}

struct Entry { page: Str, total: Int }

const PREFIX: Str = "page:";

fn main(input: Dir, counts: Kv) -> Result<Str, Str> {
  let text = match input.read("visits.txt") {
    Ok(b) => b.to_str(),
    Err(_) => { return Err("cannot read visits.txt"); }
  };

  let mut local: Map<Str, Int> = Map::new();
  for line in text.lines() {
    let p = line.trim();
    if p.len() == 0 { continue; }
    let c = local.get(p).unwrap_or(0);
    local.insert(p, c + 1);
  }

  for p in local.keys() {
    let n = local.get(p).unwrap_or(0);
    match counts.add(PREFIX + p, n) {
      Ok(_) => {}
      Err(_) => { return Err("cannot update count for " + p); }
    }
  }

  let mut entries: List<Entry> = [];
  let mut after: Option<Str> = None;
  loop {
    let page = match counts.scan(PREFIX, after, 1000) {
      Ok(x) => x,
      Err(_) => { return Err("cannot read counts"); }
    };
    for e in page {
      let name = e.key.strip_prefix(PREFIX).unwrap_or(e.key);
      let t = e.value.to_str().trim().parse_int().unwrap_or(0);
      entries.push(Entry { page: name, total: t });
    }
    if page.len() < 1000 { break; }
    after = Some(page[page.len() - 1].key);
  }

  entries.sort_by(|a, b| a.total > b.total || (a.total == b.total && a.page < b.page));

  let mut out: List<Str> = [];
  for e in entries {
    out.push(e.page + " " + e.total.to_str());
  }
  Ok(out.join("\n"))
}

fn kv_err(e: KvErr) -> Str {
  match e {
    KvErr::TooLarge => "kv error: too large",
    KvErr::Full => "kv error: full",
    KvErr::NotInt => "kv error: not int",
    KvErr::Overflow => "kv error: overflow",
  }
}

fn user_json(id: Str, name: Str, email: Str) -> Str {
  "{\"id\":" + Json::Str(id).to_json() + ",\"name\":" + Json::Str(name).to_json() + ",\"email\":" + Json::Str(email).to_json() + "}"
}

fn key(id: Str) -> Str {
  "u:" + id
}

fn run(users: Kv, line: Str) -> Result<Str, KvErr> {
  let raw = line.split(" ");
  let mut parts: List<Str> = [];
  for p in raw {
    if p.len() > 0 { parts.push(p); }
  }
  let bad = "bad " + line;
  if parts.len() == 0 { return Ok(bad); }
  let cmd = parts[0];
  if cmd == "put" && parts.len() == 4 {
    let id = parts[1];
    users.set(key(id), (parts[2] + " " + parts[3]).to_bytes())?;
    return Ok("ok " + id);
  }
  if cmd == "rename" && parts.len() == 3 {
    let id = parts[1];
    let Some(v) = users.get(key(id))? else { return Ok("missing " + id); };
    let fields = v.to_str().split(" ");
    let email = if fields.len() >= 2 { fields[1] } else { "" };
    users.set(key(id), (parts[2] + " " + email).to_bytes())?;
    return Ok("ok " + id);
  }
  if cmd == "get" && parts.len() == 2 {
    let id = parts[1];
    let Some(v) = users.get(key(id))? else { return Ok("missing " + id); };
    let fields = v.to_str().split(" ");
    let name = fields[0];
    let email = if fields.len() >= 2 { fields[1] } else { "" };
    return Ok(user_json(id, name, email));
  }
  if cmd == "del" && parts.len() == 2 {
    let id = parts[1];
    let Some(_v) = users.get(key(id))? else { return Ok("missing " + id); };
    users.delete(key(id))?;
    return Ok("ok " + id);
  }
  if cmd == "count" && parts.len() == 1 {
    let ks = users.keys("u:")?;
    return Ok("count " + ks.len().to_str());
  }
  Ok(bad)
}

fn main(input: Dir, users: Kv) -> Result<Str, Str> {
  let data = match input.read("commands.txt") {
    Ok(b) => b,
    Err(_) => return Err("cannot read commands.txt"),
  };
  let text = data.to_str();
  let mut out: List<Str> = [];
  for l in text.lines() {
    let line = l.trim();
    if line.len() == 0 { continue; }
    match run(users, line) {
      Ok(s) => out.push(s),
      Err(e) => return Err(kv_err(e)),
    }
  }
  Ok(out.join("\n"))
}

struct Event { id: Str, account: Str, cents: Int }

struct Acc { name: Str, cents: Int }

fn kerr(e: KvErr) -> Str {
  match e {
    KvErr::TooLarge => "kv error: too large",
    KvErr::Full => "kv error: full",
    KvErr::NotInt => "kv error: not an integer",
    KvErr::Overflow => "kv error: overflow",
  }
}

fn ierr(e: IoErr) -> Str {
  match e {
    IoErr::NotFound => "io error: not found",
    IoErr::Denied => "io error: denied",
    IoErr::TooLarge => "io error: too large",
    IoErr::InvalidPath => "io error: invalid path",
    IoErr::Exists => "io error: exists",
  }
}

fn parse_event(line: Str) -> Option<Event> {
  let j = line.parse_json().ok()?;
  let Json::Obj(m) = j else { return None; };
  let Json::Str(id) = m.get("id")? else { return None; };
  let Json::Str(account) = m.get("account")? else { return None; };
  let Json::Num(cents) = m.get("cents")? else { return None; };
  Some(Event { id: id, account: account, cents: cents })
}

fn apply(state: Kv, ev: Event) -> Result<Bool, Str> {
  let seen_key = "s:" + ev.id.sha256().to_hex();
  let fresh = state.swap(seen_key, None, Some("1".to_bytes())).map_err(kerr)?;
  if !fresh {
    return Ok(false);
  }
  let h = ev.account.sha256().to_hex();
  state.set("n:" + h, ev.account.to_bytes()).map_err(kerr)?;
  state.add("b:" + h, ev.cents).map_err(kerr)?;
  Ok(true)
}

fn balances(state: Kv) -> Result<List<Acc>, Str> {
  let mut accs: List<Acc> = [];
  let mut after: Option<Str> = None;
  loop {
    let page = state.scan("n:", after, 1000).map_err(kerr)?;
    for e in page {
      let Some(h) = e.key.strip_prefix("n:") else { continue; };
      let name = e.value.to_str();
      let mut cents = 0;
      if let Some(b) = state.get("b:" + h).map_err(kerr)? {
        cents = b.to_str().parse_int().unwrap_or(0);
      }
      accs.push(Acc { name: name, cents: cents });
    }
    if page.len() < 1000 {
      break;
    }
    after = Some(page[page.len() - 1].key);
  }
  accs.sort_by_key(|a| a.name);
  Ok(accs)
}

fn main(input: Dir, state: Kv) -> Result<Str, Str> {
  let text = input.read("events.jsonl").map_err(ierr)?.to_str();
  let mut applied = 0;
  let mut dup = 0;
  let mut rejected = 0;
  for raw in text.lines() {
    let line = raw.trim();
    if line.len() == 0 {
      continue;
    }
    match parse_event(line) {
      None => { rejected += 1; }
      Some(ev) => {
        if apply(state, ev)? { applied += 1; } else { dup += 1; }
      }
    }
  }
  let mut out: List<Str> = [];
  out.push("applied " + applied.to_str() + " duplicate " + dup.to_str() + " rejected " + rejected.to_str());
  for a in balances(state)? {
    out.push(a.name + " " + a.cents.to_str());
  }
  Ok(out.join("\n"))
}

fn kv_get_count(limits: Kv, key: Str) -> Result<Int, Str> {
  let v = limits.get(key).map_err(|e| "kv get failed")?;
  match v {
    None => Ok(0),
    Some(b) => {
      let s = b.to_str();
      Ok(s.trim().parse_int().unwrap_or(0))
    }
  }
}

fn kv_incr(limits: Kv, key: Str) -> Result<Int, Str> {
  limits.add(key, 1).map_err(|e| "kv add failed")
}

fn main(input: Dir, limits: Kv) -> Result<Str, Str> {
  let data = input.read("requests.txt").map_err(|e| "cannot read requests.txt")?;
  let text = data.to_str();
  let mut out: List<Str> = [];
  for raw in text.lines() {
    let line = raw.trim().replace("\t", " ");
    if line.len() == 0 { continue; }
    let fields = line.split(" ").filter(|f| f.len() > 0);
    if fields.len() != 2 { continue; }
    let Some(ts) = fields[0].parse_int() else { continue; };
    let client = fields[1];
    let window = ts / 60;
    let key = "rl:" + window.to_str() + ":" + client;
    let count = kv_get_count(limits, key)?;
    if count < 3 {
      kv_incr(limits, key)?;
      out.push(fields[0] + " " + client + " allow");
    } else {
      out.push(fields[0] + " " + client + " deny");
    }
  }
  Ok(out.join("\n"))
}

struct Player { name: Str, points: Int, played: Int }

fn kv_err(e: KvErr) -> Str {
  match e {
    KvErr::TooLarge => "kv error: too large",
    KvErr::Full => "kv error: full",
    KvErr::NotInt => "kv error: not int",
    KvErr::Overflow => "kv error: overflow",
  }
}

fn io_err(e: IoErr) -> Str {
  match e {
    IoErr::NotFound => "io error: not found",
    IoErr::Denied => "io error: denied",
    IoErr::TooLarge => "io error: too large",
    IoErr::InvalidPath => "io error: invalid path",
    IoErr::Exists => "io error: exists",
  }
}

fn tokens(line: Str) -> List<Str> {
  let mut out: List<Str> = [];
  for p in line.trim().split(" ") {
    let t = p.trim();
    if t.len() > 0 { out.push(t); }
  }
  out
}

fn bump(pts: Map<Str, Int>, name: Str, n: Int) -> Map<Str, Int> {
  let mut m = pts;
  let cur = m.get(name).unwrap_or(0);
  m.insert(name, cur + n);
  m
}

fn read_int(board: Kv, key: Str) -> Result<Int, Str> {
  let v = board.get(key).map_err(kv_err)?;
  match v {
    Some(b) => Ok(b.to_str().trim().parse_int().unwrap_or(0)),
    None => Ok(0),
  }
}

fn better(a: Player, b: Player) -> Bool {
  if a.points != b.points { return a.points > b.points; }
  if a.played != b.played { return a.played < b.played; }
  a.name < b.name
}

fn main(input: Dir, board: Kv) -> Result<Str, Str> {
  let text = input.read("games.txt").map_err(io_err)?.to_str();
  let mut pts: Map<Str, Int> = Map::new();
  let mut played: Map<Str, Int> = Map::new();
  for line in text.lines() {
    let t = tokens(line);
    if t.len() == 2 {
      pts = bump(pts, t[0], 3);
      pts = bump(pts, t[1], 0);
      played = bump(played, t[0], 1);
      played = bump(played, t[1], 1);
    } else if t.len() == 3 && t[2] == "draw" {
      pts = bump(pts, t[0], 1);
      pts = bump(pts, t[1], 1);
      played = bump(played, t[0], 1);
      played = bump(played, t[1], 1);
    }
  }
  for name in played.keys() {
    let g = played.get(name).unwrap_or(0);
    let p = pts.get(name).unwrap_or(0);
    board.add("pl:" + name, g).map_err(kv_err)?;
    board.add("pts:" + name, p).map_err(kv_err)?;
  }
  let mut players: List<Player> = [];
  for key in board.keys("pl:").map_err(kv_err)? {
    let Some(name) = key.strip_prefix("pl:") else { continue; };
    let g = read_int(board, key)?;
    let p = read_int(board, "pts:" + name)?;
    players.push(Player { name: name, points: p, played: g });
  }
  players.sort_by(better);
  let mut out: List<Str> = [];
  let mut i = 0;
  while i < players.len() && i < 3 {
    let pl = players[i];
    out.push((i + 1).to_str() + ". " + pl.name + " " + pl.points.to_str() + " " + pl.played.to_str());
    i += 1;
  }
  Ok(out.join("\n"))
}

