fn main(input: Dir, shop: Db) -> Result<Str, Str> {
  shop.exec("CREATE TABLE IF NOT EXISTS orders (order_id INTEGER PRIMARY KEY, customer TEXT NOT NULL, product TEXT NOT NULL, qty INTEGER NOT NULL, unit_cents INTEGER NOT NULL)", []).map_err(db_err)?;
  let text = input.read("orders.csv").map_err(io_err)?.to_str();
  let mut imported = 0;
  let mut skipped = 0;
  let mut rejected = 0;
  let mut first = true;
  for raw in text.lines() {
    if first { first = false; continue; }
    let line = raw.trim();
    if line == "" { continue; }
    let Some(o) = parse_row(line) else { rejected += 1; continue; };
    let n = shop.exec(
      "INSERT OR IGNORE INTO orders (order_id, customer, product, qty, unit_cents) VALUES (?, ?, ?, ?, ?)",
      [SqlValue::Int(o.id), SqlValue::Text(o.customer), SqlValue::Text(o.product), SqlValue::Int(o.qty), SqlValue::Int(o.unit)]
    ).map_err(db_err)?;
    if n == 0 { skipped += 1; } else { imported += 1; }
  }
  let mut out: List<Str> = [];
  out.push("imported " + imported.to_str() + " skipped " + skipped.to_str() + " rejected " + rejected.to_str());
  let rows = shop.query(
    "SELECT product, SUM(qty * unit_cents) AS rev, COUNT(*) FROM orders GROUP BY product ORDER BY rev DESC, product ASC LIMIT 3",
    []
  ).map_err(db_err)?;
  for r in rows {
    if r.len() < 3 { continue; }
    out.push(val_str(r[0]) + " " + val_str(r[1]) + " " + val_str(r[2]));
  }
  Ok(out.join("\n"))
}

struct Agg { country: Str, customers: Int, orders: Int, revenue: Int, top_name: Str, top_rev: Int }

fn db_err(e: DbErr) -> Str {
  match e {
    DbErr::Invalid(m) => "db invalid: " + m,
    DbErr::Denied => "db denied",
    DbErr::Busy => "db busy",
    DbErr::TooLarge => "db too large",
    DbErr::Constraint(m) => "db constraint: " + m,
  }
}

fn as_int(v: SqlValue) -> Result<Int, Str> {
  match v {
    SqlValue::Int(n) => Ok(n),
    SqlValue::Null => Ok(0),
    SqlValue::Float(f) => f.to_int().ok_or("bad number"),
    _ => Err("expected integer"),
  }
}

fn as_str(v: SqlValue) -> Result<Str, Str> {
  match v {
    SqlValue::Text(s) => Ok(s),
    _ => Err("expected text"),
  }
}

fn main(shop: Db) -> Result<Str, Str> {
  let sql = "SELECT c.id, c.name, c.country, COUNT(o.id), SUM(o.total_cents) FROM orders o JOIN customers c ON c.id = o.customer_id WHERE o.status = 'paid' AND substr(o.placed, 1, 4) = '2026' GROUP BY c.id, c.name, c.country ORDER BY c.id";
  let rows = shop.query(sql, []).map_err(db_err)?;
  let mut aggs: Map<Str, Agg> = Map::new();
  for row in rows {
    if row.len() != 5 { return Err("unexpected row shape"); }
    let name = as_str(row[1])?;
    let country = as_str(row[2])?;
    let n = as_int(row[3])?;
    let rev = as_int(row[4])?;
    let a = match aggs.get(country) {
      Some(a) => a,
      None => Agg { country: country, customers: 0, orders: 0, revenue: 0, top_name: "", top_rev: 0 },
    };
    let mut b = Agg { customers: a.customers + 1, orders: a.orders + n, revenue: a.revenue + rev, ..a };
    if a.customers == 0 || rev > a.top_rev {
      b.top_name = name;
      b.top_rev = rev;
    }
    aggs.insert(country, b);
  }
  let mut list: List<Agg> = [];
  for k in aggs.keys() {
    if let Some(a) = aggs.get(k) { list.push(a); }
  }
  list.sort_by(|a, b| a.revenue > b.revenue || (a.revenue == b.revenue && a.country < b.country));
  let mut lines: List<Str> = [];
  let mut tot_orders = 0;
  let mut tot_rev = 0;
  for a in list {
    tot_orders = tot_orders + a.orders;
    tot_rev = tot_rev + a.revenue;
    lines.push(a.country + " customers=" + a.customers.to_str() + " orders=" + a.orders.to_str()
      + " revenue=" + a.revenue.to_str() + " top=" + a.top_name);
  }
  lines.push("total orders=" + tot_orders.to_str() + " revenue=" + tot_rev.to_str());
  Ok(lines.join("\n"))
}

struct Batch { name: Str, lines: List<Str> }
struct Move { sku: Str, delta: Int }

const IMAX: Int = 9223372036854775807;

fn db_err(e: DbErr) -> Str {
  match e {
    DbErr::Invalid(m) => "db invalid: " + m,
    DbErr::Denied => "db denied",
    DbErr::Busy => "db busy",
    DbErr::TooLarge => "db too large",
    DbErr::Constraint(m) => "db constraint: " + m,
  }
}

fn io_err(e: IoErr) -> Str {
  match e {
    IoErr::NotFound => "moves.txt not found",
    IoErr::Denied => "read denied",
    IoErr::TooLarge => "file too large",
    IoErr::InvalidPath => "invalid path",
    IoErr::Exists => "exists",
  }
}

fn all_digits(s: Str) -> Bool {
  if s.len() == 0 { return false; }
  for c in s.chars() {
    if !"0123456789".contains(c) { return false; }
  }
  true
}

fn parse_move(t: Str) -> Option<Move> {
  let parts = t.split(" ").filter(|p| p.len() > 0);
  if parts.len() != 2 { return None; }
  let sku = parts[0];
  let amt = parts[1];
  let mut neg = false;
  let mut rest = "";
  if let Some(r) = amt.strip_prefix("+") {
    rest = r;
  } else if let Some(r) = amt.strip_prefix("-") {
    rest = r;
    neg = true;
  } else {
    return None;
  }
  if !all_digits(rest) { return None; }
  let n = rest.parse_int()?;
  if n <= 0 { return None; }
  if neg { Some(Move { sku: sku, delta: 0 - n }) } else { Some(Move { sku: sku, delta: n }) }
}

fn current_qty(db: Db, sku: Str) -> Result<Int, Str> {
  let rows = db.query("SELECT qty FROM inventory WHERE sku = ?", [SqlValue::Text(sku)]).map_err(db_err)?;
  if rows.len() == 0 { return Ok(0); }
  match rows[0][0] {
    SqlValue::Int(n) => Ok(n),
    _ => Ok(0),
  }
}

fn already_applied(db: Db, name: Str) -> Result<Bool, Str> {
  let rows = db.query("SELECT 1 FROM batches WHERE name = ?", [SqlValue::Text(name)]).map_err(db_err)?;
  Ok(rows.len() > 0)
}

fn apply_batch(db: Db, b: Batch) -> Result<Str, Str> {
  if already_applied(db, b.name)? { return Ok("skipped"); }
  let mut q: HashMap<Str, Int> = HashMap::new();
  for line in b.lines {
    let Some(m) = parse_move(line) else { return Ok("rejected"); };
    let mut cur = 0;
    if let Some(v) = q.get(m.sku) {
      cur = v;
    } else {
      cur = current_qty(db, m.sku)?;
    }
    if m.delta > 0 && cur > IMAX - m.delta { return Ok("rejected"); }
    let next = cur + m.delta;
    if next < 0 { return Ok("rejected"); }
    q.insert(m.sku, next);
  }
  let mut stmts: List<Str> = ["INSERT INTO batches(name) VALUES (?)"];
  let mut params: List<List<SqlValue>> = [[SqlValue::Text(b.name)]];
  for k in q.keys() {
    let v = q.get(k).unwrap_or(0);
    stmts.push("INSERT INTO inventory(sku, qty) VALUES (?, ?) ON CONFLICT(sku) DO UPDATE SET qty = excluded.qty");
    params.push([SqlValue::Text(k), SqlValue::Int(v)]);
  }
  db.transaction(stmts, params).map_err(db_err)?;
  Ok("applied")
}

fn main(input: Dir, stock: Db) -> Result<Str, Str> {
  stock.exec("CREATE TABLE IF NOT EXISTS inventory (sku TEXT PRIMARY KEY, qty INTEGER NOT NULL)", []).map_err(db_err)?;
  stock.exec("CREATE TABLE IF NOT EXISTS batches (name TEXT PRIMARY KEY)", []).map_err(db_err)?;
  let text = input.read("moves.txt").map_err(io_err)?.to_str();
  let mut batches: List<Batch> = [];
  for line in text.lines() {
    let t = line.trim();
    if t.len() == 0 { continue; }
    if let Some(n) = t.strip_prefix("batch ") {
      batches.push(Batch { name: n.trim(), lines: [] });
      continue;
    }
    if batches.len() == 0 { continue; }
    let i = batches.len() - 1;
    batches[i].lines.push(t);
  }
  let mut out = "";
  for b in batches {
    let status = apply_batch(stock, b)?;
    out = out + b.name + " " + status + "\n";
  }
  let rows = stock.query("SELECT sku, qty FROM inventory WHERE qty != 0 ORDER BY sku", []).map_err(db_err)?;
  for r in rows {
    let mut sku = "";
    let mut qty = 0;
    if let SqlValue::Text(s) = r[0] { sku = s; }
    if let SqlValue::Int(n) = r[1] { qty = n; }
    out = out + sku + " " + qty.to_str() + "\n";
  }
  Ok(out)
}

fn db_err(e: DbErr) -> Str {
  match e {
    DbErr::Invalid(m) => "db invalid: " + m,
    DbErr::Denied => "db denied",
    DbErr::Busy => "db busy",
    DbErr::TooLarge => "db too large",
    DbErr::Constraint(m) => "db constraint: " + m,
  }
}

fn io_err(e: IoErr) -> Str {
  match e {
    IoErr::NotFound => "contacts.csv not found",
    IoErr::Denied => "read denied",
    IoErr::TooLarge => "file too large",
    IoErr::InvalidPath => "invalid path",
    IoErr::Exists => "exists",
  }
}

fn text(v: SqlValue) -> Str {
  match v {
    SqlValue::Text(s) => s,
    SqlValue::Int(n) => n.to_str(),
    SqlValue::Float(f) => f.to_str(),
    SqlValue::Blob(b) => b.to_hex(),
    SqlValue::Null => "",
  }
}

fn int_of(v: SqlValue) -> Int {
  match v {
    SqlValue::Int(n) => n,
    _ => 0,
  }
}

fn main(input: Dir, crm: Db) -> Result<Str, Str> {
  crm.exec("CREATE TABLE IF NOT EXISTS contacts (email TEXT PRIMARY KEY, name TEXT NOT NULL, phone TEXT NOT NULL)", []).map_err(db_err)?;
  let content = input.read("contacts.csv").map_err(io_err)?.to_str();
  let mut inserted = 0;
  let mut updated = 0;
  let mut unchanged = 0;
  let mut rejected = 0;
  let mut first = true;
  for raw in content.lines() {
    if first {
      first = false;
      continue;
    }
    if raw.trim() == "" {
      continue;
    }
    let parts = raw.split(",");
    if parts.len() != 3 {
      rejected += 1;
      continue;
    }
    let email = parts[0].trim().to_lowercase();
    let name = parts[1].trim();
    let phone = parts[2].trim();
    if !email.contains("@") {
      rejected += 1;
      continue;
    }
    let rows = crm.query("SELECT name, phone FROM contacts WHERE email = ?", [SqlValue::Text(email)]).map_err(db_err)?;
    if rows.len() == 0 {
      crm.exec("INSERT INTO contacts (email, name, phone) VALUES (?, ?, ?)",
        [SqlValue::Text(email), SqlValue::Text(name), SqlValue::Text(phone)]).map_err(db_err)?;
      inserted += 1;
    } else {
      let row = rows[0];
      let old_name = text(row[0]);
      let old_phone = text(row[1]);
      if old_name != name || old_phone != phone {
        crm.exec("UPDATE contacts SET name = ?, phone = ? WHERE email = ?",
          [SqlValue::Text(name), SqlValue::Text(phone), SqlValue::Text(email)]).map_err(db_err)?;
        updated += 1;
      } else {
        unchanged += 1;
      }
    }
  }
  let count_rows = crm.query("SELECT COUNT(*) FROM contacts", []).map_err(db_err)?;
  let mut total = 0;
  if count_rows.len() > 0 {
    total = int_of(count_rows[0][0]);
  }
  let missing_rows = crm.query("SELECT email FROM contacts WHERE phone = ''", []).map_err(db_err)?;
  let mut missing: List<Str> = [];
  for r in missing_rows {
    missing.push(text(r[0]));
  }
  missing.sort();
  let mut out: List<Str> = [];
  out.push("inserted " + inserted.to_str() + " updated " + updated.to_str() + " unchanged " + unchanged.to_str() + " rejected " + rejected.to_str());
  out.push("contacts " + total.to_str());
  for e in missing {
    out.push("missing phone: " + e);
  }
  Ok(out.join("\n"))
}

struct Resp { status: Int, body: Json }

struct Entry { name: Str, count: Int }

fn err_json(msg: Str) -> Json {
  let mut m: Map<Str, Json> = Map::new();
  m.insert("error", Json::Str(msg));
  Json::Obj(m)
}

fn entry_json(name: Str, count: Int) -> Json {
  let mut m: Map<Str, Json> = Map::new();
  m.insert("name", Json::Str(name));
  m.insert("count", Json::Num(count));
  Json::Obj(m)
}

fn valid_name(n: Str) -> Bool {
  if n.len() < 1 || n.len() > 32 { return false; }
  for b in n.to_bytes() {
    let ok = (b >= 97 && b <= 122) || (b >= 48 && b <= 57) || b == 45;
    if !ok { return false; }
  }
  true
}

fn key_of(name: Str) -> Str {
  "c/" + name
}

fn parse_count(v: Option<Bytes>) -> Int {
  match v {
    Some(b) => b.to_str().parse_int().unwrap_or(0),
    None => 0,
  }
}

fn bad_name() -> Resp {
  Resp { status: 400, body: err_json("bad name") }
}

fn not_found() -> Resp {
  Resp { status: 404, body: err_json("not found") }
}

fn top(counts: Kv) -> Result<Resp, KvErr> {
  let mut all: List<Entry> = [];
  let mut after: Option<Str> = None;
  loop {
    let page = counts.scan("c/", after, 1000)?;
    for e in page {
      let name = e.key.slice(2, e.key.len());
      let c = e.value.to_str().parse_int().unwrap_or(0);
      all.push(Entry { name: name, count: c });
    }
    if page.len() < 1000 { break; }
    after = Some(page[page.len() - 1].key);
  }
  all.sort_by(|a, b| a.count > b.count || (a.count == b.count && a.name < b.name));
  let mut out: List<Json> = [];
  let mut i = 0;
  while i < all.len() && i < 3 {
    out.push(entry_json(all[i].name, all[i].count));
    i += 1;
  }
  Ok(Resp { status: 200, body: Json::Arr(out) })
}

fn route(method: Str, path: Str, counts: Kv) -> Result<Resp, KvErr> {
  if method == "POST" {
    if let Some(name) = path.strip_prefix("/hit/") {
      if !valid_name(name) { return Ok(bad_name()); }
      let n = counts.add(key_of(name), 1)?;
      return Ok(Resp { status: 200, body: entry_json(name, n) });
    }
    return Ok(not_found());
  }
  if method == "GET" {
    if path == "/top" {
      return top(counts);
    }
    if let Some(name) = path.strip_prefix("/count/") {
      if !valid_name(name) { return Ok(bad_name()); }
      let v = counts.get(key_of(name))?;
      return Ok(Resp { status: 200, body: entry_json(name, parse_count(v)) });
    }
    return Ok(not_found());
  }
  Ok(not_found())
}

fn main(req: Incoming, res: Outgoing, counts: Kv) -> Result<Str, WebErr> {
  let r = match route(req.method(), req.target(), counts) {
    Ok(r) => r,
    Err(_) => Resp { status: 500, body: err_json("storage error") },
  };
  res.send(r.status, ["content-type"], ["application/json"], r.body.to_json().to_bytes())?;
  Ok("ok")
}

struct Todo { id: Int, title: Str, done: Bool }

fn kv<T>(r: Result<T, KvErr>) -> Result<T, Str> {
  match r {
    Ok(v) => Ok(v),
    Err(_) => Err("storage error"),
  }
}

fn pad(n: Int) -> Str {
  let mut s = n.to_str();
  while s.len() < 20 { s = "0" + s; }
  s
}

fn key(id: Int) -> Str { "todo/" + pad(id) }

fn valid_utf8(b: Bytes) -> Bool {
  let n = b.len();
  let mut i = 0;
  while i < n {
    let c = b[i];
    if c < 128 { i += 1; continue; }
    let mut need = 0;
    let mut min = 0;
    let mut cp = 0;
    if c >= 194 && c <= 223 { need = 1; min = 128; cp = c - 192; }
    else if c >= 224 && c <= 239 { need = 2; min = 2048; cp = c - 224; }
    else if c >= 240 && c <= 244 { need = 3; min = 65536; cp = c - 240; }
    else { return false; }
    if i + need >= n { return false; }
    for k in 1..need + 1 {
      let d = b[i + k];
      if d < 128 || d > 191 { return false; }
      cp = cp * 64 + (d - 128);
    }
    if cp < min || cp > 1114111 || (cp >= 55296 && cp <= 57343) { return false; }
    i += need + 1;
  }
  true
}

fn todo_json(t: Todo) -> Json {
  let mut m: Map<Str, Json> = Map::new();
  m.insert("id", Json::Num(t.id));
  m.insert("title", Json::Str(t.title));
  m.insert("done", Json::Bool(t.done));
  Json::Obj(m)
}

fn parse_todo(b: Bytes) -> Option<Todo> {
  if !valid_utf8(b) { return None; }
  let j = b.to_str().parse_json().ok()?;
  Some(Todo {
    id: j.get("id")?.as_int()?,
    title: j.get("title")?.as_str()?,
    done: j.get("done")?.as_bool()?,
  })
}

fn body_json(req: Incoming) -> Option<Json> {
  let b = req.body();
  if !valid_utf8(b) { return None; }
  b.to_str().parse_json().ok()
}

fn reply(res: Outgoing, status: Int, j: Json) -> Result<(), Str> {
  res.send(status, ["content-type"], ["application/json"], j.to_json().to_bytes())
    .map_err(|e| "send error")
}

fn reply_err(res: Outgoing, status: Int, msg: Str) -> Result<(), Str> {
  let mut m: Map<Str, Json> = Map::new();
  m.insert("error", Json::Str(msg));
  reply(res, status, Json::Obj(m))
}

fn not_found(res: Outgoing) -> Result<(), Str> {
  reply_err(res, 404, "not found")
}

fn parse_id(s: Str) -> Option<Int> {
  if s.len() == 0 || s.len() > 18 { return None; }
  for c in s.chars() {
    if c < "0" || c > "9" { return None; }
  }
  let n = s.parse_int()?;
  if n <= 0 { return None; }
  Some(n)
}

fn create(req: Incoming, res: Outgoing, store: Kv) -> Result<(), Str> {
  let Some(j) = body_json(req) else { return reply_err(res, 400, "title required"); };
  let Some(m) = j.as_map() else { return reply_err(res, 400, "title required"); };
  let Some(tj) = m.get("title") else { return reply_err(res, 400, "title required"); };
  let Some(raw) = tj.as_str() else { return reply_err(res, 400, "title required"); };
  let title = raw.trim();
  if title.len() == 0 { return reply_err(res, 400, "title required"); }
  let id = kv(store.add("next_id", 1))?;
  let t = Todo { id: id, title: title, done: false };
  kv(store.set(key(id), todo_json(t).to_json().to_bytes()))?;
  reply(res, 201, todo_json(t))
}

fn list(res: Outgoing, store: Kv, query: Str) -> Result<(), Str> {
  let mut filter: Option<Bool> = None;
  for part in query.split("&") {
    if part == "done=true" { filter = Some(true); }
    else if part == "done=false" { filter = Some(false); }
  }
  let mut after: Option<Str> = None;
  let mut out: List<Json> = [];
  loop {
    let page = kv(store.scan("todo/", after, 1000))?;
    for e in page {
      if let Some(t) = parse_todo(e.value) {
        let keep = match filter {
          Some(d) => t.done == d,
          None => true,
        };
        if keep { out.push(todo_json(t)); }
      }
    }
    if page.len() < 1000 { break; }
    after = Some(page[page.len() - 1].key);
  }
  reply(res, 200, Json::Arr(out))
}

fn apply_update(j: Json, t: Todo) -> Option<Todo> {
  let m = j.as_map()?;
  let mut r = t;
  if let Some(x) = m.get("title") {
    let s = x.as_str()?;
    let s2 = s.trim();
    if s2.len() == 0 { return None; }
    r.title = s2;
  }
  if let Some(x) = m.get("done") {
    r.done = x.as_bool()?;
  }
  Some(r)
}

fn get_one(res: Outgoing, store: Kv, id: Int) -> Result<(), Str> {
  let Some(b) = kv(store.get(key(id)))? else { return not_found(res); };
  let Some(t) = parse_todo(b) else { return not_found(res); };
  reply(res, 200, todo_json(t))
}

fn patch(req: Incoming, res: Outgoing, store: Kv, id: Int) -> Result<(), Str> {
  let body = body_json(req);
  let k = key(id);
  loop {
    let Some(old) = kv(store.get(k))? else { return not_found(res); };
    let Some(t) = parse_todo(old) else { return not_found(res); };
    let Some(j) = body else { return reply_err(res, 400, "bad update"); };
    let Some(nt) = apply_update(j, t) else { return reply_err(res, 400, "bad update"); };
    let nb = todo_json(nt).to_json().to_bytes();
    if kv(store.swap(k, Some(old), Some(nb)))? {
      return reply(res, 200, todo_json(nt));
    }
  }
}

fn delete(res: Outgoing, store: Kv, id: Int) -> Result<(), Str> {
  let k = key(id);
  loop {
    let Some(old) = kv(store.get(k))? else { return not_found(res); };
    let none: Option<Bytes> = None;
    if kv(store.swap(k, Some(old), none))? {
      return res.send(204, [], [], "".to_bytes()).map_err(|e| "send error");
    }
  }
}

fn handle(req: Incoming, res: Outgoing, store: Kv) -> Result<(), Str> {
  let target = req.target();
  let mut path = target;
  let mut query = "";
  if let Some(i) = target.find("?") {
    path = target.slice(0, i);
    query = target.slice(i + 1, target.len());
  }
  let method = req.method();
  if path == "/todos" {
    if method == "POST" { return create(req, res, store); }
    if method == "GET" { return list(res, store, query); }
    return not_found(res);
  }
  let Some(rest) = path.strip_prefix("/todos/") else { return not_found(res); };
  let Some(id) = parse_id(rest) else { return not_found(res); };
  if method == "GET" { return get_one(res, store, id); }
  if method == "PATCH" { return patch(req, res, store, id); }
  if method == "DELETE" { return delete(res, store, id); }
  not_found(res)
}

fn main(req: Incoming, res: Outgoing, store: Kv) -> Str {
  match handle(req, res, store) {
    Ok(_) => "ok",
    Err(e) => {
      if reply_err(res, 500, e).is_err() {}
      e
    }
  }
}

