fn is_digits(s: Str) -> Bool {
  if s.len() == 0 { return false; }
  for c in s.to_bytes() {
    if c < 48 || c > 57 { return false; }
  }
  true
}

fn validate(text: Str) -> Option<NewNote> {
  let doc = text.parse_json().ok()?;
  let Json::Obj(m) = doc else { return None; };
  let Some(Json::Str(title)) = m.get("title") else { return None; };
  if title.len() == 0 { return None; }
  let Some(Json::Str(body)) = m.get("body") else { return None; };
  let mut tags: List<Str> = [];
  if let Some(t) = m.get("tags") {
    let Json::Arr(items) = t else { return None; };
    for it in items {
      let Json::Str(s) = it else { return None; };
      let l = s.to_lowercase();
      if !tags.contains(l) { tags.push(l); }
    }
  }
  Some(NewNote { title: title, body: body, tags: tags })
}

fn sql_int(v: SqlValue) -> Int {
  match v { SqlValue::Int(n) => n, _ => 0 }
}

fn sql_str(v: SqlValue) -> Str {
  match v { SqlValue::Text(s) => s, _ => "" }
}

fn parse_tags(s: Str) -> List<Str> {
  let mut out: List<Str> = [];
  if let Ok(j) = s.parse_json() {
    if let Some(items) = j.as_list() {
      for it in items {
        if let Some(t) = it.as_str() { out.push(t); }
      }
    }
  }
  out
}

fn row_note(row: List<SqlValue>) -> Note {
  Note { id: sql_int(row[0]), title: sql_str(row[1]), body: sql_str(row[2]), tags: parse_tags(sql_str(row[3])) }
}

fn note_json(n: Note) -> Json {
  let mut m: Map<Str, Json> = Map::new();
  m.insert("id", Json::Num(n.id));
  m.insert("title", Json::Str(n.title));
  m.insert("body", Json::Str(n.body));
  m.insert("tags", Json::Arr(n.tags.map(|t| Json::Str(t))));
  Json::Obj(m)
}

fn create(req: Incoming, db: Db) -> Result<Resp, DbErr> {
  let Some(n) = validate(req.body().to_str()) else { return Ok(err(400, "invalid note")); };
  let tags_text = Json::Arr(n.tags.map(|t| Json::Str(t))).to_json();
  let rows = db.query("INSERT INTO notes (title, body, tags) VALUES (?, ?, ?) RETURNING id",
    [SqlValue::Text(n.title), SqlValue::Text(n.body), SqlValue::Text(tags_text)])?;
  let mut id = 0;
  if rows.len() > 0 { id = sql_int(rows[0][0]); }
  let mut m: Map<Str, Json> = Map::new();
  m.insert("id", Json::Num(id));
  Ok(Resp { status: 201, body: Json::Obj(m) })
}

fn list(query: Str, db: Db) -> Result<Resp, DbErr> {
  let mut tag: Option<Str> = None;
  let mut word: Option<Str> = None;
  for p in query.split("&") {
    let kv = p.split("=");
    if kv.len() == 2 {
      if kv[0] == "tag" { tag = Some(kv[1].to_lowercase()); }
      else if kv[0] == "q" { word = Some(kv[1]); }
    }
  }
  let rows = db.query("SELECT id, title, body, tags FROM notes ORDER BY id DESC", [])?;
  let mut out: List<Json> = [];
  for row in rows {
    let n = row_note(row);
    if let Some(t) = tag {
      if !n.tags.contains(t) { continue; }
    }
    if let Some(w) = word {
      if !(n.title.contains(w) || n.body.contains(w)) { continue; }
    }
    let mut m: Map<Str, Json> = Map::new();
    m.insert("id", Json::Num(n.id));
    m.insert("title", Json::Str(n.title));
    out.push(Json::Obj(m));
  }
  Ok(Resp { status: 200, body: Json::Arr(out) })
}

fn get_one(id: Int, db: Db) -> Result<Resp, DbErr> {
  let rows = db.query("SELECT id, title, body, tags FROM notes WHERE id = ?", [SqlValue::Int(id)])?;
  if rows.len() == 0 { return Ok(not_found()); }
  Ok(Resp { status: 200, body: note_json(row_note(rows[0])) })
}

fn delete_one(id: Int, db: Db) -> Result<Resp, DbErr> {
  let changed = db.exec("DELETE FROM notes WHERE id = ?", [SqlValue::Int(id)])?;
  if changed == 0 { return Ok(not_found()); }
  let mut m: Map<Str, Json> = Map::new();
  m.insert("deleted", Json::Num(id));
  Ok(Resp { status: 200, body: Json::Obj(m) })
}

fn handle(req: Incoming, db: Db) -> Result<Resp, DbErr> {
  db.exec("CREATE TABLE IF NOT EXISTS notes (id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, body TEXT NOT NULL, tags TEXT NOT NULL)", [])?;
  let target = req.target();
  let mut path = target;
  let mut query = "";
  if let Some(i) = target.find("?") {
    path = target.slice(0, i);
    query = target.slice(i + 1, target.len());
  }
  let method = req.method();
  let segs = path.split("/");
  if segs.len() == 2 && segs[0] == "" && segs[1] == "notes" {
    if method == "POST" { return create(req, db); }
    if method == "GET" { return list(query, db); }
    return Ok(not_found());
  }
  if segs.len() == 3 && segs[0] == "" && segs[1] == "notes" && is_digits(segs[2]) {
    let Some(id) = segs[2].parse_int() else { return Ok(not_found()); };
    if method == "GET" { return get_one(id, db); }
    if method == "DELETE" { return delete_one(id, db); }
  }
  Ok(not_found())
}

fn main(req: Incoming, res: Outgoing, db: Db) -> Str {
  let r = match handle(req, db) {
    Ok(r) => r,
    Err(_) => err(500, "internal error"),
  };
  let _ = res.send(r.status, ["content-type"], ["application/json"], r.body.to_json().to_bytes());
  r.status.to_str()
}

struct Station { id: Str, name: Str }

fn fmt(t: Int) -> Str {
  let mut a = t;
  let mut s = "";
  if t < 0 {
    a = 0 - t;
    s = "-";
  }
  s + (a / 10).to_str() + "." + (a % 10).to_str()
}

fn summarize(api: Http, s: Station) -> Str {
  let path = "/stations/" + s.id + "/readings";
  let body = match api.get(path) {
    Ok(b) => b,
    Err(_) => return s.name + " unavailable",
  };
  let doc = match body.to_str().parse_json() {
    Ok(j) => j,
    Err(_) => return s.name + " unavailable",
  };
  let readings = doc.get("readings").and_then(|j| j.as_list()).unwrap_or([]);
  let mut temps: List<Int> = [];
  for r in readings {
    if let Some(t) = r.get("temp").and_then(|j| j.as_int()) {
      temps.push(t);
    }
  }
  let n = temps.len();
  if n == 0 {
    return s.name + " no data";
  }
  let mut mn = temps[0];
  let mut mx = temps[0];
  let mut sum = 0;
  for t in temps {
    mn = mn.min(t);
    mx = mx.max(t);
    sum = sum + t;
  }
  let avg = sum / n;
  s.name + " min=" + fmt(mn) + " max=" + fmt(mx) + " avg=" + fmt(avg) + " n=" + n.to_str()
}

fn main(api: Http) -> Result<Str, Str> {
  let body = api.get("/stations").map_err(|e| "stations request failed")?;
  let doc = body.to_str().parse_json()?;
  let list = doc.get("stations").and_then(|j| j.as_list()).unwrap_or([]);
  let mut stations: List<Station> = [];
  for j in list {
    let Some(id) = j.get("id").and_then(|x| x.as_str()) else { continue; };
    let Some(name) = j.get("name").and_then(|x| x.as_str()) else { continue; };
    stations.push(Station { id: id, name: name });
  }
  stations.sort_by_key(|s| s.name);
  let mut lines: List<Str> = [];
  for s in stations {
    lines.push(summarize(api, s));
  }
  Ok(lines.join("\n"))
}

fn http_err(e: HttpErr) -> Str {
  match e {
    HttpErr::Denied => "http denied",
    HttpErr::Timeout => "http timeout",
    HttpErr::TooLarge => "http too large",
    HttpErr::Status(n) => "http status " + n.to_str(),
    HttpErr::Invalid => "http invalid",
  }
}

fn main(api: Http) -> Result<Str, Str> {
  let mut page = 1;
  let mut count = 0;
  let mut paid: Map<Str, Int> = Map::new();
  let mut refunded = 0;
  let mut has_largest = false;
  let mut largest_id = 0;
  let mut largest_cents = 0;
  let mut fetched = 0;
  loop {
    fetched += 1;
    if fetched > 100000 { return Err("too many pages"); }
    let body = api.get("/orders?page=" + page.to_str()).map_err(http_err)?;
    let doc = body.to_str().parse_json()?;
    let orders = doc.get("orders").and_then(|j| j.as_list()).ok_or("missing orders")?;
    for o in orders {
      count += 1;
      let status = o.get("status").and_then(|j| j.as_str()).unwrap_or("");
      if status == "paid" {
        let id = o.get("id").and_then(|j| j.as_int()).ok_or("missing id")?;
        let cents = o.get("cents").and_then(|j| j.as_int()).ok_or("missing cents")?;
        let cur = o.get("currency").and_then(|j| j.as_str()).ok_or("missing currency")?;
        let prev = paid.get(cur).unwrap_or(0);
        paid.insert(cur, prev + cents);
        if !has_largest || cents > largest_cents || (cents == largest_cents && id < largest_id) {
          has_largest = true;
          largest_id = id;
          largest_cents = cents;
        }
      } else if status == "refunded" {
        refunded += 1;
      }
    }
    match doc.get("next") {
      Some(Json::Num(m)) => { page = m; }
      _ => break,
    }
  }
  let mut pc: Map<Str, Json> = Map::new();
  for k in paid.keys() {
    pc.insert(k, Json::Num(paid.get(k).unwrap_or(0)));
  }
  let mut obj: Map<Str, Json> = Map::new();
  obj.insert("orders", Json::Num(count));
  obj.insert("paid_cents", Json::Obj(pc));
  obj.insert("refunded", Json::Num(refunded));
  if has_largest {
    obj.insert("largest", Json::Num(largest_id));
  } else {
    obj.insert("largest", Json::Null);
  }
  let payload = Json::Obj(obj).to_json();
  let r = api.send("POST", "/summaries", ["content-type: application/json"], payload.to_bytes()).map_err(http_err)?;
  if r.status != 201 {
    return Err("status " + r.status.to_str());
  }
  let resp = r.body.to_str().parse_json()?;
  let id = resp.get("id").and_then(|j| j.as_str()).ok_or("missing summary id")?;
  Ok(id)
}

struct St {
  order: List<Str>,
  vals: Map<Str, Str>,
  hits: Int,
  misses: Int,
  evictions: Int,
}

const STATE_KEY: Str = "lru_state";

fn io_str(e: IoErr) -> Str {
  match e {
    IoErr::NotFound => "io error: not found",
    IoErr::Denied => "io error: denied",
    IoErr::TooLarge => "io error: too large",
    IoErr::InvalidPath => "io error: invalid path",
    IoErr::Exists => "io error: exists",
  }
}

fn kv_str(e: KvErr) -> Str {
  match e {
    KvErr::TooLarge => "kv error: too large",
    KvErr::Full => "kv error: full",
    KvErr::NotInt => "kv error: not int",
    KvErr::Overflow => "kv error: overflow",
  }
}

fn empty_state() -> St {
  St { order: [], vals: Map::new(), hits: 0, misses: 0, evictions: 0 }
}

fn decode(text: Str) -> Result<St, Str> {
  let j = text.parse_json()?;
  let order_j = j.get("order").and_then(|x| x.as_list()).unwrap_or([]);
  let mut order: List<Str> = [];
  for o in order_j {
    if let Some(s) = o.as_str() { order.push(s); }
  }
  let mut vals: Map<Str, Str> = Map::new();
  if let Some(m) = j.get("vals").and_then(|x| x.as_map()) {
    for k in m.keys() {
      if let Some(v) = m.get(k) {
        if let Some(s) = v.as_str() { vals.insert(k, s); }
      }
    }
  }
  let hits = j.get("hits").and_then(|x| x.as_int()).unwrap_or(0);
  let misses = j.get("misses").and_then(|x| x.as_int()).unwrap_or(0);
  let evictions = j.get("evictions").and_then(|x| x.as_int()).unwrap_or(0);
  Ok(St { order: order, vals: vals, hits: hits, misses: misses, evictions: evictions })
}

fn encode(s: St) -> Str {
  let mut obj: Map<Str, Json> = Map::new();
  obj.insert("order", Json::Arr(s.order.map(|k| Json::Str(k))));
  let mut vm: Map<Str, Json> = Map::new();
  for k in s.vals.keys() {
    if let Some(v) = s.vals.get(k) { vm.insert(k, Json::Str(v)); }
  }
  obj.insert("vals", Json::Obj(vm));
  obj.insert("hits", Json::Num(s.hits));
  obj.insert("misses", Json::Num(s.misses));
  obj.insert("evictions", Json::Num(s.evictions));
  Json::Obj(obj).to_json()
}

fn touch(order: List<Str>, k: Str) -> List<Str> {
  let mut out: List<Str> = [k];
  for x in order { if x != k { out.push(x); } }
  out
}

fn without(order: List<Str>, k: Str) -> List<Str> {
  let mut out: List<Str> = [];
  for x in order { if x != k { out.push(x); } }
  out
}

fn load(cache: Kv) -> Result<St, Str> {
  let got = cache.get(STATE_KEY).map_err(kv_str)?;
  match got {
    None => Ok(empty_state()),
    Some(b) => decode(b.to_str()),
  }
}

fn save(cache: Kv, s: St) -> Result<(), Str> {
  cache.set(STATE_KEY, encode(s).to_bytes()).map_err(kv_str)
}

fn main(input: Dir, cache: Kv) -> Result<Str, Str> {
  let text = input.read("ops.txt").map_err(io_str)?.to_str();
  let lines = text.lines();
  if lines.len() == 0 { return Err("missing capacity line"); }
  let head = lines[0].split(" ");
  if head.len() != 2 || head[0] != "capacity" { return Err("bad capacity line"); }
  let Some(cap) = head[1].parse_int() else { return Err("bad capacity"); };
  if cap < 1 { return Err("bad capacity"); }

  let mut st = load(cache)?;
  let mut out: List<Str> = [];

  while st.order.len() > cap {
    let Some(k) = st.order.pop() else { break; };
    st.vals.remove(k);
    st.evictions += 1;
    out.push("evict " + k);
  }

  for i in 1..lines.len() {
    let line = lines[i];
    let n = i + 1;
    if line == "" { continue; }
    if let Some(rest) = line.strip_prefix("put ") {
      let Some(sp) = rest.find(" ") else {
        out.push("bad line " + n.to_str());
        continue;
      };
      let key = rest.slice(0, sp);
      let value = rest.slice(sp + 1, rest.len());
      if key == "" || value == "" {
        out.push("bad line " + n.to_str());
        continue;
      }
      if st.vals.get(key).is_none() && st.order.len() >= cap {
        if let Some(ev) = st.order.pop() {
          st.vals.remove(ev);
          st.evictions += 1;
          out.push("evict " + ev);
        }
      }
      st.vals.insert(key, value);
      st.order = touch(st.order, key);
      continue;
    }
    let parts = line.split(" ");
    if parts.len() != 2 || parts[1] == "" {
      out.push("bad line " + n.to_str());
      continue;
    }
    let key = parts[1];
    if parts[0] == "get" {
      match st.vals.get(key) {
        Some(v) => {
          st.hits += 1;
          st.order = touch(st.order, key);
          out.push(key + "=" + v);
        }
        None => {
          st.misses += 1;
          out.push(key + " miss");
        }
      }
    } else if parts[0] == "del" {
      if st.vals.get(key).is_some() {
        st.vals.remove(key);
        st.order = without(st.order, key);
      }
    } else {
      out.push("bad line " + n.to_str());
    }
  }

  if st.order.len() == 0 {
    out.push("cache:");
  } else {
    out.push("cache: " + st.order.join(","));
  }
  out.push("stats hits " + st.hits.to_str() + " misses " + st.misses.to_str() + " evictions " + st.evictions.to_str());

  save(cache, st)?;
  Ok(out.join("\n"))
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("packages.json")?.to_str();
  let doc = match text.parse_json() {
    Ok(j) => j,
    Err(_) => { return Ok("error: not an object"); }
  };
  let Json::Obj(obj) = doc else { return Ok("error: not an object"); };

  let mut deps: Map<Str, List<Str>> = Map::new();
  let mut invalid: List<Str> = [];
  for k in obj.keys() {
    let v = obj.get(k).unwrap_or(Json::Null);
    let mut ok = true;
    let mut ds: List<Str> = [];
    match v {
      Json::Arr(items) => {
        for it in items {
          match it {
            Json::Str(s) => { if !ds.contains(s) { ds.push(s); } }
            _ => { ok = false; }
          }
        }
      }
      _ => { ok = false; }
    }
    if ok { deps.insert(k, ds); } else { invalid.push(k); }
  }
  let pkgs = deps.keys();

  // missing
  let mut missing: Map<Str, List<Str>> = Map::new();
  for p in pkgs {
    for d in deps.get(p).unwrap_or([]) {
      if deps.get(d).is_none() {
        let mut l = missing.get(d).unwrap_or([]);
        l.push(p);
        missing.insert(d, l);
      }
    }
  }

  // stages
  let mut stage: Map<Str, Int> = Map::new();
  let mut changed = true;
  while changed {
    changed = false;
    for p in pkgs {
      if stage.get(p).is_some() { continue; }
      let mut ok = true;
      let mut mx = 0;
      for d in deps.get(p).unwrap_or([]) {
        match stage.get(d) {
          Some(s) => { mx = mx.max(s); }
          None => { ok = false; break; }
        }
      }
      if ok { stage.insert(p, mx + 1); changed = true; }
    }
  }

  let mut unbuilt: List<Str> = [];
  for p in pkgs { if stage.get(p).is_none() { unbuilt.push(p); } }

  // reachability among unbuilt valid packages
  let mut reach: Map<Str, Map<Str, Bool>> = Map::new();
  for p in unbuilt {
    let mut seen: Map<Str, Bool> = Map::new();
    let mut stack: List<Str> = [p];
    while stack.len() > 0 {
      let Some(x) = stack.pop() else { break; };
      for d in deps.get(x).unwrap_or([]) {
        if deps.get(d).is_some() && stage.get(d).is_none() && seen.get(d).is_none() {
          seen.insert(d, true);
          stack.push(d);
        }
      }
    }
    reach.insert(p, seen);
  }

  let mut in_cycle: Map<Str, Bool> = Map::new();
  let mut cycles: List<Str> = [];
  for p in unbuilt {
    if in_cycle.get(p).is_some() { continue; }
    let rp = reach.get(p).unwrap_or(Map::new());
    if rp.get(p).is_none() { continue; }
    let mut group: List<Str> = [];
    for q in unbuilt {
      if rp.get(q).is_some() {
        let rq = reach.get(q).unwrap_or(Map::new());
        if rq.get(p).is_some() {
          group.push(q);
          in_cycle.insert(q, true);
        }
      }
    }
    cycles.push("cycle: " + group.join(", "));
  }

  let mut lines: List<Str> = [];
  let mut maxs = 0;
  for p in pkgs {
    match stage.get(p) { Some(s) => { maxs = maxs.max(s); } None => {} }
  }
  for n in 1..(maxs + 1) {
    let mut names: List<Str> = [];
    for p in pkgs {
      if stage.get(p) == Some(n) { names.push(p); }
    }
    if names.len() > 0 {
      lines.push("stage " + n.to_str() + ": " + names.join(", "));
    }
  }
  for c in cycles { lines.push(c); }
  for m in missing.keys() {
    let l = missing.get(m).unwrap_or([]);
    lines.push("missing: " + m + " (needed by " + l.join(", ") + ")");
  }
  if invalid.len() > 0 {
    invalid.sort();
    lines.push("invalid: " + invalid.join(", "));
  }
  let mut blocked: List<Str> = [];
  for p in unbuilt { if in_cycle.get(p).is_none() { blocked.push(p); } }
  if blocked.len() > 0 { lines.push("blocked: " + blocked.join(", ")); }
  lines.push("built " + stage.len().to_str() + " of " + pkgs.len().to_str());
  Ok(lines.join("\n"))
}

struct Booking { start: Int, end: Int, who: Str }
struct Iv { s: Int, e: Int }
struct Conf { s: Int, text: Str }

fn digit(b: Int) -> Option<Int> {
  if b >= 48 && b <= 57 { Some(b - 48) } else { None }
}

fn parse_time(s: Str, allow24: Bool) -> Option<Int> {
  let b = s.to_bytes();
  if b.len() != 5 { return None; }
  if b[2] != 58 { return None; }
  let h = digit(b[0])? * 10 + digit(b[1])?;
  let m = digit(b[3])? * 10 + digit(b[4])?;
  if m > 59 { return None; }
  if h == 24 {
    if allow24 && m == 0 { return Some(1440); }
    return None;
  }
  if h > 23 { return None; }
  Some(h * 60 + m)
}

fn two(n: Int) -> Str {
  if n < 10 { "0" + n.to_str() } else { n.to_str() }
}

fn fmt(t: Int) -> Str {
  two(t / 60) + ":" + two(t % 60)
}

fn fmt_iv(s: Int, e: Int) -> Str {
  fmt(s) + "-" + fmt(e)
}

fn report(room: Str, day: Str, bs: List<Booking>) -> List<Str> {
  let mut out: List<Str> = [];
  out.push(room + " " + day);
  let mut sorted = bs;
  sorted.sort_by(|a: Booking, b: Booking| a.start < b.start || (a.start == b.start && a.end < b.end));
  let mut merged: List<Iv> = [];
  for b in sorted {
    let n = merged.len();
    if n > 0 && b.start <= merged[n - 1].e {
      if b.end > merged[n - 1].e { merged[n - 1].e = b.end; }
    } else {
      merged.push(Iv { s: b.start, e: b.end });
    }
  }
  let busy: List<Str> = merged.map(|iv| fmt_iv(iv.s, iv.e));
  out.push("  busy " + busy.join(", "));
  let mut free: List<Str> = [];
  let mut cur = 540;
  for iv in merged {
    if iv.s > cur {
      let ge = iv.s.min(1080);
      if ge - cur >= 30 { free.push(fmt_iv(cur, ge)); }
    }
    cur = cur.max(iv.e);
  }
  if 1080 - cur >= 30 { free.push(fmt_iv(cur, 1080)); }
  if free.len() == 0 {
    out.push("  free none");
  } else {
    out.push("  free " + free.join(", "));
  }
  let mut confs: List<Conf> = [];
  let n = bs.len();
  for i in 0..n {
    for j in (i + 1)..n {
      let a = bs[i];
      let b = bs[j];
      let os = a.start.max(b.start);
      let oe = a.end.min(b.end);
      if oe > os {
        let names = if a.who <= b.who { a.who + "/" + b.who } else { b.who + "/" + a.who };
        confs.push(Conf { s: os, text: "  conflict " + names + " " + fmt_iv(os, oe) });
      }
    }
  }
  confs.sort_by(|a: Conf, b: Conf| a.s < b.s || (a.s == b.s && a.text < b.text));
  for c in confs { out.push(c.text); }
  out
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("bookings.csv")?.to_str();
  let lines = text.lines();
  let mut skipped: List<Str> = [];
  let mut seen: HashMap<Str, Bool> = HashMap::new();
  let mut rooms: Map<Str, Map<Str, List<Booking>>> = Map::new();
  let mut idx = 0;
  for line in lines {
    idx += 1;
    if idx == 1 { continue; }
    if line.trim().len() == 0 { continue; }
    let f = line.split(",");
    if f.len() != 5 { skipped.push(idx.to_str()); continue; }
    let Some(st) = parse_time(f[2], false) else { skipped.push(idx.to_str()); continue; };
    let Some(en) = parse_time(f[3], true) else { skipped.push(idx.to_str()); continue; };
    if en <= st { skipped.push(idx.to_str()); continue; }
    let key = f.join(",");
    if seen.get(key).is_some() { continue; }
    seen.insert(key, true);
    let mut days = rooms.get(f[0]).unwrap_or(Map::new());
    let mut list = days.get(f[1]).unwrap_or([]);
    list.push(Booking { start: st, end: en, who: f[4] });
    days.insert(f[1], list);
    rooms.insert(f[0], days);
  }
  let mut out: List<Str> = [];
  for room in rooms.keys() {
    let days = rooms.get(room).unwrap_or(Map::new());
    for day in days.keys() {
      let bs = days.get(day).unwrap_or([]);
      for l in report(room, day, bs) { out.push(l); }
    }
  }
  if skipped.len() == 0 {
    out.push("skipped: none");
  } else {
    out.push("skipped: " + skipped.join(", "));
  }
  Ok(out.join("\n"))
}

struct E { path: Str, msg: Str }

fn type_ok(t: Str, v: Json) -> Bool {
  match v {
    Json::Obj(_) => t == "object",
    Json::Arr(_) => t == "array",
    Json::Str(_) => t == "string",
    Json::Num(_) => t == "integer" || t == "number",
    Json::Float(_) => t == "number",
    Json::Bool(_) => t == "boolean",
    Json::Null => t == "null",
  }
}

fn less_than(v: Json, b: Int) -> Bool {
  match v {
    Json::Num(n) => n < b,
    Json::Float(f) => f < b.to_float(),
    _ => false,
  }
}

fn greater_than(v: Json, b: Int) -> Bool {
  match v {
    Json::Num(n) => n > b,
    Json::Float(f) => f > b.to_float(),
    _ => false,
  }
}

fn int_key(s: Json, k: Str) -> Option<Int> {
  s.get(k).and_then(|j| j.as_int())
}

fn validate(s: Json, v: Json, path: Str, errs: List<E>) -> List<E> {
  let mut out = errs;
  let t = s.get("type").and_then(|j| j.as_str()).unwrap_or("");
  if !type_ok(t, v) {
    out.push(E { path: path, msg: "expected " + t });
    return out;
  }
  if let Json::Obj(m) = v {
    let props: Map<Str, Json> = s.get("properties").and_then(|j| j.as_map()).unwrap_or(Map::new());
    let reqs: List<Json> = s.get("required").and_then(|j| j.as_list()).unwrap_or([]);
    for r in reqs {
      if let Some(name) = r.as_str() {
        if m.get(name).is_none() {
          out.push(E { path: path + "." + name, msg: "missing required field" });
        }
      }
    }
    let additional = s.get("additional") != Some(Json::Bool(false));
    for k in m.keys() {
      let Some(fv) = m.get(k) else { continue; };
      match props.get(k) {
        Some(ps) => { out = validate(ps, fv, path + "." + k, out); }
        None => {
          if !additional {
            out.push(E { path: path + "." + k, msg: "unexpected field" });
          }
        }
      }
    }
  } else if let Json::Arr(items) = v {
    if let Some(n) = int_key(s, "min_items") {
      if items.len() < n {
        out.push(E { path: path, msg: "fewer than " + n.to_str() + " items" });
      }
    }
    if let Some(is) = s.get("items") {
      let mut i = 0;
      for it in items {
        out = validate(is, it, path + "[" + i.to_str() + "]", out);
        i = i + 1;
      }
    }
  } else if let Json::Str(st) = v {
    let len = st.chars().len();
    let mut msg = "";
    if let Some(n) = int_key(s, "min_length") {
      if len < n { msg = "shorter than " + n.to_str(); }
    }
    if msg == "" {
      if let Some(n) = int_key(s, "max_length") {
        if len > n { msg = "longer than " + n.to_str(); }
      }
    }
    if msg == "" {
      if let Some(en) = s.get("enum").and_then(|j| j.as_list()) {
        if !en.contains(Json::Str(st)) { msg = "not in enum"; }
      }
    }
    if msg != "" { out.push(E { path: path, msg: msg }); }
  } else if t == "integer" || t == "number" {
    let mut msg = "";
    if let Some(n) = int_key(s, "minimum") {
      if less_than(v, n) { msg = "less than " + n.to_str(); }
    }
    if msg == "" {
      if let Some(n) = int_key(s, "maximum") {
        if greater_than(v, n) { msg = "greater than " + n.to_str(); }
      }
    }
    if msg != "" { out.push(E { path: path, msg: msg }); }
  }
  out
}

fn main(input: Dir) -> Result<Str, Str> {
  let stext = input.read("schema.json").map_err(|e| "cannot read schema.json")?.to_str();
  let schema = stext.parse_json()?;
  let rtext = input.read("records.jsonl").map_err(|e| "cannot read records.jsonl")?.to_str();
  let mut lines: List<Str> = [];
  let mut valid = 0;
  let mut total = 0;
  let mut n = 0;
  for line in rtext.lines() {
    n = n + 1;
    if line.trim().len() == 0 { continue; }
    total = total + 1;
    let prefix = "line " + n.to_str() + ": ";
    match line.parse_json() {
      Err(_) => { lines.push(prefix + "invalid JSON"); }
      Ok(v) => {
        let empty: List<E> = [];
        let mut errs = validate(schema, v, "$", empty);
        if errs.len() == 0 {
          valid = valid + 1;
          lines.push(prefix + "ok");
        } else {
          errs.sort_by(|a, b| a.path < b.path || (a.path == b.path && a.msg < b.msg));
          for e in errs {
            lines.push(prefix + e.path + ": " + e.msg);
          }
        }
      }
    }
  }
  lines.push("valid " + valid.to_str() + " of " + total.to_str());
  Ok(lines.join("\n"))
}

struct Parsed { id: Str, version: Int, line: Str }

fn parse_rec(line: Str) -> Option<Parsed> {
  let j = line.parse_json().ok()?;
  let Json::Obj(m) = j else { return None; };
  let id = m.get("id")?.as_str()?;
  let v = m.get("version")?.as_int()?;
  Some(Parsed { id: id, version: v, line: line })
}

fn kerr(e: KvErr) -> Str { "kv error" }

fn last_pushed(state: Kv, id: Str) -> Result<Option<Int>, Str> {
  let r = state.get("ver:" + id).map_err(kerr)?;
  match r {
    Some(b) => Ok(b.to_str().parse_int()),
    None => Ok(None),
  }
}

fn send_round(api: Http, ids: List<Str>, recs: Map<Str, Parsed>) -> List<Result<HttpResponse, HttpErr>> {
  let mut out: List<Result<HttpResponse, HttpErr>> = [];
  let mut i = 0;
  while i < ids.len() {
    let end = (i + 64).min(ids.len());
    let mut reqs: List<HttpRequest> = [];
    for k in i..end {
      let id = ids[k];
      let line = match recs.get(id) { Some(p) => p.line, None => "" };
      reqs.push(HttpRequest {
        method: "PUT",
        path: "/records/" + id,
        headers: ["content-type: application/json"],
        body: line.to_bytes(),
        timeout_ms: 0,
      });
    }
    let res = api.send_all(reqs);
    for r in res { out.push(r); }
    i = end;
  }
  out
}

fn main(input: Dir, state: Kv, api: Http) -> Result<Str, Str> {
  let text = input.read("records.jsonl").map_err(|e: IoErr| "cannot read records.jsonl")?.to_str();
  let ls = text.lines();
  let mut out = "";
  let mut recs: Map<Str, Parsed> = Map::new();
  for i in 0..ls.len() {
    let line = ls[i].trim();
    if line.len() == 0 { continue; }
    match parse_rec(line) {
      Some(p) => { recs.insert(p.id, p); }
      None => { out = out + "line " + (i + 1).to_str() + " invalid\n"; }
    }
  }
  let mut outcome: Map<Str, Str> = Map::new();
  let mut pending: List<Str> = [];
  for id in recs.keys() {
    let Some(p) = recs.get(id) else { continue; };
    let prev = last_pushed(state, id)?;
    let push = match prev { Some(v) => p.version > v, None => true };
    if push { pending.push(id); } else { outcome.insert(id, "unchanged"); }
  }
  let mut synced = 0;
  let mut rejected = 0;
  let mut failed = 0;
  for round in 0..3 {
    if pending.len() == 0 { break; }
    let res = send_round(api, pending, recs);
    let mut next: List<Str> = [];
    for k in 0..pending.len() {
      let id = pending[k];
      let mut retry = false;
      match res[k] {
        Ok(r) => {
          if r.status >= 200 && r.status < 300 {
            let ver = match recs.get(id) { Some(p) => p.version, None => 0 };
            state.set("ver:" + id, ver.to_str().to_bytes()).map_err(kerr)?;
            outcome.insert(id, "synced");
            synced += 1;
          } else if r.status >= 400 && r.status < 500 {
            outcome.insert(id, "rejected " + r.status.to_str());
            rejected += 1;
          } else {
            retry = true;
          }
        }
        Err(_) => { retry = true; }
      }
      if retry {
        if round == 2 {
          outcome.insert(id, "failed");
          failed += 1;
        } else {
          next.push(id);
        }
      }
    }
    pending = next;
  }
  let mut unchanged = 0;
  for id in outcome.keys() {
    let o = outcome.get(id).unwrap_or("");
    if o == "unchanged" { unchanged += 1; }
    out = out + id + " " + o + "\n";
  }
  out = out + "synced " + synced.to_str() + " unchanged " + unchanged.to_str()
    + " rejected " + rejected.to_str() + " failed " + failed.to_str();
  Ok(out)
}

enum Outcome { Done, Fail(Str), Dup }

fn pad2(n: Int) -> Str {
  if n < 10 { "0" + n.to_str() } else { n.to_str() }
}

fn pad4(n: Int) -> Str {
  let mut s = n.to_str();
  while s.len() < 4 { s = "0" + s; }
  s
}

fn fdiv(a: Int, b: Int) -> Int {
  let q = a / b;
  if (a % b != 0) && ((a < 0) != (b < 0)) { q - 1 } else { q }
}

fn fmt_time(ms: Int) -> Str {
  let secs = fdiv(ms, 1000);
  let days = fdiv(secs, 86400);
  let rem = secs - days * 86400;
  let hh = rem / 3600;
  let mm = (rem % 3600) / 60;
  let ss = rem % 60;
  let z = days + 719468;
  let era = fdiv(z, 146097);
  let doe = z - era * 146097;
  let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
  let mut y = yoe + era * 400;
  let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
  let mp = (5 * doy + 2) / 153;
  let d = doy - (153 * mp + 2) / 5 + 1;
  let m = if mp < 10 { mp + 3 } else { mp - 9 };
  if m <= 2 { y = y + 1; }
  pad4(y) + "-" + pad2(m) + "-" + pad2(d) + "T" + pad2(hh) + ":" + pad2(mm) + ":" + pad2(ss) + "Z"
}

fn q(db: Db, sql: Str, params: List<SqlValue>) -> Result<List<List<SqlValue>>, Str> {
  db.query(sql, params).map_err(|e| "db error: " + sql)
}

fn ex(db: Db, sql: Str, params: List<SqlValue>) -> Result<Int, Str> {
  db.exec(sql, params).map_err(|e| "db error: " + sql)
}

fn as_int(v: SqlValue) -> Int {
  match v {
    SqlValue::Int(n) => n,
    _ => 0,
  }
}

fn as_text(v: SqlValue) -> Str {
  match v {
    SqlValue::Text(s) => s,
    _ => "",
  }
}

fn balance(db: Db, name: Str) -> Result<Option<Int>, Str> {
  let rows = q(db, "SELECT balance FROM accounts WHERE name = ? AND closed = 0", [SqlValue::Text(name)])?;
  if rows.len() == 0 { return Ok(None); }
  Ok(Some(as_int(rows[0][0])))
}

fn do_open(db: Db, words: List<Str>, now: Str) -> Result<Outcome, Str> {
  if words.len() != 3 { return Ok(Outcome::Fail("malformed")); }
  let Some(c) = words[2].parse_int() else { return Ok(Outcome::Fail("malformed")); };
  if c < 0 { return Ok(Outcome::Fail("bad amount")); }
  let name = words[1];
  let rows = q(db, "SELECT 1 FROM accounts WHERE name = ?", [SqlValue::Text(name)])?;
  if rows.len() > 0 { return Ok(Outcome::Fail("account exists")); }
  ex(db, "INSERT INTO accounts (name, balance, last, closed) VALUES (?, ?, ?, 0)",
     [SqlValue::Text(name), SqlValue::Int(c), SqlValue::Text(now)])?;
  Ok(Outcome::Done)
}

fn do_close(db: Db, words: List<Str>) -> Result<Outcome, Str> {
  if words.len() != 2 { return Ok(Outcome::Fail("malformed")); }
  let name = words[1];
  let Some(b) = balance(db, name)? else { return Ok(Outcome::Fail("no account " + name)); };
  if b != 0 { return Ok(Outcome::Fail("balance not zero")); }
  ex(db, "UPDATE accounts SET closed = 1 WHERE name = ?", [SqlValue::Text(name)])?;
  Ok(Outcome::Done)
}

fn do_transfer(db: Db, words: List<Str>, now: Str) -> Result<Outcome, Str> {
  if words.len() != 5 { return Ok(Outcome::Fail("malformed")); }
  let Some(c) = words[4].parse_int() else { return Ok(Outcome::Fail("malformed")); };
  let id = words[1];
  let from = words[2];
  let to = words[3];
  let prev = q(db, "SELECT src, dst, cents FROM transfers WHERE id = ?", [SqlValue::Text(id)])?;
  if prev.len() > 0 {
    let r = prev[0];
    if as_text(r[0]) == from && as_text(r[1]) == to && as_int(r[2]) == c {
      return Ok(Outcome::Dup);
    }
    return Ok(Outcome::Fail("id reused"));
  }
  if c <= 0 { return Ok(Outcome::Fail("bad amount")); }
  if from == to { return Ok(Outcome::Fail("same account")); }
  let Some(fb) = balance(db, from)? else { return Ok(Outcome::Fail("no account " + from)); };
  let Some(tb) = balance(db, to)? else { return Ok(Outcome::Fail("no account " + to)); };
  if fb < c { return Ok(Outcome::Fail("insufficient funds")); }
  if tb > 9223372036854775807 - c { return Ok(Outcome::Fail("overflow")); }
  let stmts = [
    "UPDATE accounts SET balance = ?, last = ? WHERE name = ?",
    "UPDATE accounts SET balance = ?, last = ? WHERE name = ?",
    "INSERT INTO transfers (id, src, dst, cents) VALUES (?, ?, ?, ?)",
  ];
  let params: List<List<SqlValue>> = [
    [SqlValue::Int(fb - c), SqlValue::Text(now), SqlValue::Text(from)],
    [SqlValue::Int(tb + c), SqlValue::Text(now), SqlValue::Text(to)],
    [SqlValue::Text(id), SqlValue::Text(from), SqlValue::Text(to), SqlValue::Int(c)],
  ];
  db.transaction(stmts, params).map_err(|e| "db error: transaction")?;
  Ok(Outcome::Done)
}

fn process(db: Db, words: List<Str>, now: Str) -> Result<Outcome, Str> {
  match words[0] {
    "open" => do_open(db, words, now),
    "transfer" => do_transfer(db, words, now),
    "close" => do_close(db, words),
    _ => Ok(Outcome::Fail("malformed")),
  }
}

fn main(input: Dir, db: Db, log: Log, clock: Clock) -> Result<Str, Str> {
  let now = fmt_time(clock.now_ms());
  ex(db, "CREATE TABLE IF NOT EXISTS accounts (name TEXT PRIMARY KEY, balance INTEGER NOT NULL, last TEXT NOT NULL, closed INTEGER NOT NULL)", [])?;
  ex(db, "CREATE TABLE IF NOT EXISTS transfers (id TEXT PRIMARY KEY, src TEXT NOT NULL, dst TEXT NOT NULL, cents INTEGER NOT NULL)", [])?;
  let bytes = input.read("ops.txt").map_err(|e| "cannot read ops.txt")?;
  let text = bytes.to_str();
  let mut ok = 0;
  let mut failed = 0;
  let mut dup = 0;
  let mut n = 0;
  for line in text.lines() {
    n = n + 1;
    if line.trim() == "" { continue; }
    let words = line.split(" ");
    match process(db, words, now)? {
      Outcome::Done => { ok = ok + 1; }
      Outcome::Dup => { dup = dup + 1; }
      Outcome::Fail(msg) => {
        failed = failed + 1;
        log.write(now + " line " + n.to_str() + ": " + msg).map_err(|e| "log error")?;
      }
    }
  }
  let mut out: List<Str> = ["ok " + ok.to_str() + " failed " + failed.to_str() + " duplicate " + dup.to_str()];
  let rows = q(db, "SELECT name, balance, last FROM accounts WHERE closed = 0 ORDER BY name", [])?;
  for r in rows {
    out.push(as_text(r[0]) + " " + as_int(r[1]).to_str() + " last " + as_text(r[2]));
  }
  Ok(out.join("\n"))
}

struct Resp { status: Int, body: Str }

struct User { salt: Str, hash: Str, logins: Int, fails: Int, locked_until: Int }

struct Creds { name: Str, password: Json }

const SESSION_MS: Int = 1800000;
const LOCK_MS: Int = 900000;

fn obj1(k: Str, v: Json) -> Str {
  let mut m: Map<Str, Json> = Map::new();
  m.insert(k, v);
  Json::Obj(m).to_json()
}

fn err(status: Int, msg: Str) -> Resp {
  Resp { status: status, body: obj1("error", Json::Str(msg)) }
}

fn utf8_ok(b: Bytes) -> Bool {
  let n = b.len();
  let mut i = 0;
  while i < n {
    let c = b[i];
    let mut need = 0;
    let mut lo = 128;
    let mut hi = 191;
    if c < 128 { i += 1; continue; }
    else if c >= 194 && c <= 223 { need = 1; }
    else if c == 224 { need = 2; lo = 160; }
    else if (c >= 225 && c <= 236) || c == 238 || c == 239 { need = 2; }
    else if c == 237 { need = 2; hi = 159; }
    else if c == 240 { need = 3; lo = 144; }
    else if c >= 241 && c <= 243 { need = 3; }
    else if c == 244 { need = 3; hi = 143; }
    else { return false; }
    if i + need >= n { return false; }
    let c1 = b[i + 1];
    if c1 < lo || c1 > hi { return false; }
    for k in 2..need + 1 {
      let ck = b[i + k];
      if ck < 128 || ck > 191 { return false; }
    }
    i = i + need + 1;
  }
  true
}

fn body_json(body: Bytes) -> Option<Json> {
  if !utf8_ok(body) { return None; }
  body.to_str().parse_json().ok()
}

fn creds(body: Bytes) -> Option<Creds> {
  let j = body_json(body)?;
  let _m = j.as_map()?;
  let name = j.get("name")?.as_str()?;
  let pw = j.get("password").unwrap_or(Json::Null);
  Some(Creds { name: name, password: pw })
}

fn valid_name(name: Str) -> Bool {
  if name.len() < 3 || name.len() > 20 { return false; }
  let allowed = "abcdefghijklmnopqrstuvwxyz0123456789_";
  for ch in name.chars() {
    if !allowed.contains(ch) { return false; }
  }
  true
}

fn valid_token(t: Str) -> Bool {
  if t.len() != 32 { return false; }
  let allowed = "0123456789abcdef";
  for ch in t.chars() {
    if !allowed.contains(ch) { return false; }
  }
  true
}

fn hash_pw(salt: Str, pw: Str) -> Str {
  (salt + ":" + pw).sha256().to_hex()
}

fn encode_user(u: User) -> Bytes {
  let mut m: Map<Str, Json> = Map::new();
  m.insert("salt", Json::Str(u.salt));
  m.insert("hash", Json::Str(u.hash));
  m.insert("logins", Json::Num(u.logins));
  m.insert("fails", Json::Num(u.fails));
  m.insert("locked_until", Json::Num(u.locked_until));
  Json::Obj(m).to_json().to_bytes()
}

fn decode_user(b: Bytes) -> Option<User> {
  let j = body_json(b)?;
  Some(User {
    salt: j.get("salt")?.as_str()?,
    hash: j.get("hash")?.as_str()?,
    logins: j.get("logins")?.as_int()?,
    fails: j.get("fails")?.as_int()?,
    locked_until: j.get("locked_until")?.as_int()?,
  })
}

fn bearer(req: Incoming) -> Option<Str> {
  let names = req.header_names();
  let values = req.header_values();
  for i in 0..names.len() {
    if names[i] == "authorization" && i < values.len() {
      let v = values[i].trim();
      let t = v.strip_prefix("Bearer ")?.trim();
      if valid_token(t) { return Some(t); }
      return None;
    }
  }
  None
}

fn create_user(req: Incoming, store: Kv, rng: Rng) -> Result<Resp, KvErr> {
  let Some(c) = creds(req.body()) else { return Ok(err(400, "invalid")); };
  let Some(pw) = c.password.as_str() else { return Ok(err(400, "invalid")); };
  if !valid_name(c.name) || pw.len() < 8 { return Ok(err(400, "invalid")); }
  let salt = rng.bytes(16).to_hex();
  let u = User { salt: salt, hash: hash_pw(salt, pw), logins: 0, fails: 0, locked_until: 0 };
  let created = store.swap("user:" + c.name, None, Some(encode_user(u)))?;
  if created {
    Ok(Resp { status: 201, body: obj1("name", Json::Str(c.name)) })
  } else {
    Ok(err(409, "name taken"))
  }
}

fn login(req: Incoming, store: Kv, clock: Clock, rng: Rng) -> Result<Resp, KvErr> {
  let Some(c) = creds(req.body()) else { return Ok(err(401, "bad credentials")); };
  if !valid_name(c.name) { return Ok(err(401, "bad credentials")); }
  let key = "user:" + c.name;
  loop {
    let Some(raw) = store.get(key)? else { return Ok(err(401, "bad credentials")); };
    let Some(u) = decode_user(raw) else { return Ok(err(401, "bad credentials")); };
    let now = clock.now_ms();
    if now < u.locked_until { return Ok(err(429, "locked")); }
    let Some(pw) = c.password.as_str() else { return Ok(err(401, "bad credentials")); };
    if hash_pw(u.salt, pw).ct_eq(u.hash) {
      let nu = User { fails: 0, logins: u.logins + 1, ..u };
      if store.swap(key, Some(raw), Some(encode_user(nu)))? {
        let token = rng.bytes(16).to_hex();
        let mut m: Map<Str, Json> = Map::new();
        m.insert("name", Json::Str(c.name));
        m.insert("exp", Json::Num(now + SESSION_MS));
        store.set("sess:" + token, Json::Obj(m).to_json().to_bytes())?;
        let mut r: Map<Str, Json> = Map::new();
        r.insert("token", Json::Str(token));
        r.insert("expires_in", Json::Num(1800));
        return Ok(Resp { status: 200, body: Json::Obj(r).to_json() });
      }
    } else {
      let mut fails = u.fails + 1;
      let mut locked = u.locked_until;
      if fails >= 3 {
        fails = 0;
        locked = now + LOCK_MS;
      }
      let nu = User { fails: fails, locked_until: locked, ..u };
      if store.swap(key, Some(raw), Some(encode_user(nu)))? {
        return Ok(err(401, "bad credentials"));
      }
    }
  }
}

struct Session { name: Str, exp: Int }

fn get_session(store: Kv, clock: Clock, token: Str) -> Result<Option<Session>, KvErr> {
  let key = "sess:" + token;
  let Some(raw) = store.get(key)? else { return Ok(None); };
  let Some(j) = body_json(raw) else { return Ok(None); };
  let name = j.get("name").and_then(|x| x.as_str());
  let exp = j.get("exp").and_then(|x| x.as_int());
  let Some(n) = name else { return Ok(None); };
  let Some(e) = exp else { return Ok(None); };
  if clock.now_ms() >= e {
    store.delete(key)?;
    return Ok(None);
  }
  Ok(Some(Session { name: n, exp: e }))
}

fn me(req: Incoming, store: Kv, clock: Clock) -> Result<Resp, KvErr> {
  let Some(token) = bearer(req) else { return Ok(err(401, "unauthorized")); };
  let Some(s) = get_session(store, clock, token)? else { return Ok(err(401, "unauthorized")); };
  let now = clock.now_ms();
  let mut m: Map<Str, Json> = Map::new();
  m.insert("name", Json::Str(s.name));
  m.insert("exp", Json::Num(now + SESSION_MS));
  store.set("sess:" + token, Json::Obj(m).to_json().to_bytes())?;
  let mut logins = 0;
  if let Some(raw) = store.get("user:" + s.name)? {
    if let Some(u) = decode_user(raw) { logins = u.logins; }
  }
  let mut r: Map<Str, Json> = Map::new();
  r.insert("name", Json::Str(s.name));
  r.insert("logins", Json::Num(logins));
  Ok(Resp { status: 200, body: Json::Obj(r).to_json() })
}

fn logout(req: Incoming, store: Kv, clock: Clock) -> Result<Resp, KvErr> {
  let Some(token) = bearer(req) else { return Ok(err(401, "unauthorized")); };
  let Some(_s) = get_session(store, clock, token)? else { return Ok(err(401, "unauthorized")); };
  store.delete("sess:" + token)?;
  Ok(Resp { status: 204, body: "" })
}

fn handle(req: Incoming, store: Kv, clock: Clock, rng: Rng) -> Result<Resp, KvErr> {
  let path = req.target().split("?")[0];
  let method = req.method();
  if method == "POST" && path == "/users" {
    create_user(req, store, rng)
  } else if method == "POST" && path == "/login" {
    login(req, store, clock, rng)
  } else if method == "GET" && path == "/me" {
    me(req, store, clock)
  } else if method == "POST" && path == "/logout" {
    logout(req, store, clock)
  } else {
    Ok(err(404, "not found"))
  }
}

fn main(req: Incoming, res: Outgoing, store: Kv, clock: Clock, rng: Rng) -> Str {
  let r = match handle(req, store, clock, rng) {
    Ok(r) => r,
    Err(_) => err(500, "internal"),
  };
  let sent = if r.status == 204 {
    res.send(204, [], [], "".to_bytes())
  } else {
    res.send(r.status, ["content-type"], ["application/json"], r.body.to_bytes())
  };
  match sent {
    Ok(_) => r.status.to_str(),
    Err(_) => "send failed",
  }
}

const COLS: Str = "id, account, cents, currency, status, refunded";

struct Resp { status: Int, body: Str }

fn err(status: Int, msg: Str) -> Resp {
  let mut m: Map<Str, Json> = Map::new();
  m.insert("error", Json::Str(msg));
  Resp { status: status, body: Json::Obj(m).to_json() }
}

fn nf() -> Resp { err(404, "not found") }

fn int_of(v: SqlValue) -> Int {
  match v { SqlValue::Int(n) => n, _ => 0 }
}

fn str_of(v: SqlValue) -> Str {
  match v { SqlValue::Text(s) => s, _ => "" }
}

fn row_json(r: List<SqlValue>) -> Json {
  let mut m: Map<Str, Json> = Map::new();
  m.insert("id", Json::Str("pay_" + int_of(r[0]).to_str()));
  m.insert("account", Json::Str(str_of(r[1])));
  m.insert("cents", Json::Num(int_of(r[2])));
  m.insert("currency", Json::Str(str_of(r[3])));
  m.insert("status", Json::Str(str_of(r[4])));
  m.insert("refunded", Json::Num(int_of(r[5])));
  Json::Obj(m)
}

fn ok_payment(status: Int, r: List<SqlValue>) -> Resp {
  Resp { status: status, body: row_json(r).to_json() }
}

fn schema(db: Db) -> Result<(), DbErr> {
  db.exec("CREATE TABLE IF NOT EXISTS payments (id INTEGER PRIMARY KEY AUTOINCREMENT, account TEXT NOT NULL, cents INTEGER NOT NULL, currency TEXT NOT NULL, status TEXT NOT NULL, refunded INTEGER NOT NULL)", [])?;
  db.exec("CREATE TABLE IF NOT EXISTS idem (k TEXT PRIMARY KEY, method TEXT NOT NULL, path TEXT NOT NULL, body TEXT NOT NULL, status INTEGER NOT NULL, resp TEXT NOT NULL)", [])?;
  db.exec("CREATE INDEX IF NOT EXISTS payments_account ON payments(account, id)", [])?;
  Ok(())
}

fn is_utf8(b: Bytes) -> Bool {
  let n = b.len();
  let mut i = 0;
  while i < n {
    let c = b[i];
    if c < 128 { i += 1; continue; }
    let mut need = 0;
    let mut min = 0;
    let mut cp = 0;
    if c >= 194 && c <= 223 { need = 1; min = 128; cp = c - 192; }
    else if c >= 224 && c <= 239 { need = 2; min = 2048; cp = c - 224; }
    else if c >= 240 && c <= 244 { need = 3; min = 65536; cp = c - 240; }
    else { return false; }
    if i + need >= n + 0 && i + need > n - 1 { return false; }
    for k in 1..need + 1 {
      let d = b[i + k];
      if d < 128 || d > 191 { return false; }
      cp = cp * 64 + (d - 128);
    }
    if cp < min || cp > 1114111 || (cp >= 55296 && cp <= 57343) { return false; }
    i = i + need + 1;
  }
  true
}

fn parse_body(b: Bytes) -> Option<Json> {
  if !is_utf8(b) { return None; }
  b.to_str().parse_json().ok()
}

fn canon(b: Bytes) -> Str {
  if !is_utf8(b) { return "x:" + b.to_hex(); }
  let s = b.to_str();
  match s.parse_json() {
    Ok(j) => "j:" + j.to_json(),
    Err(_) => "r:" + s,
  }
}

fn hexval(c: Int) -> Int {
  if c >= 48 && c <= 57 { c - 48 }
  else if c >= 97 && c <= 102 { c - 87 }
  else if c >= 65 && c <= 70 { c - 55 }
  else { -1 }
}

fn decode(s: Str) -> Str {
  let b = s.to_bytes();
  let mut out = "".to_bytes();
  let mut i = 0;
  while i < b.len() {
    let c = b[i];
    if c == 43 { out.push(32); i += 1; }
    else if c == 37 && i + 2 < b.len() + 0 + 1 && i + 2 <= b.len() - 1 && hexval(b[i + 1]) >= 0 && hexval(b[i + 2]) >= 0 {
      out.push(hexval(b[i + 1]) * 16 + hexval(b[i + 2]));
      i += 3;
    } else { out.push(c); i += 1; }
  }
  if is_utf8(out) { out.to_str() } else { s }
}

fn query_param(query: Str, name: Str) -> Option<Str> {
  if query == "" { return None; }
  for part in query.split("&") {
    let mut k = part;
    let mut v = "";
    if let Some(p) = part.find("=") {
      k = part.slice(0, p);
      v = part.slice(p + 1, part.len());
    }
    if decode(k) == name { return Some(decode(v)); }
  }
  None
}

fn parse_id(s: Str) -> Option<Int> {
  let rest = s.strip_prefix("pay_")?;
  let n = rest.parse_int()?;
  if n <= 0 || n.to_str() != rest { return None; }
  Some(n)
}

fn header(req: Incoming, name: Str) -> Option<Str> {
  let names = req.header_names();
  let vals = req.header_values();
  for i in 0..names.len() {
    if names[i] == name && i < vals.len() { return Some(vals[i]); }
  }
  None
}

fn load(db: Db, id: Int) -> Result<Option<List<SqlValue>>, DbErr> {
  let rows = db.query("SELECT " + COLS + " FROM payments WHERE id = ?", [SqlValue::Int(id)])?;
  if rows.len() == 0 { Ok(None) } else { Ok(Some(rows[0])) }
}

fn create(db: Db, body: Bytes) -> Result<Resp, DbErr> {
  let bad = err(422, "invalid payment");
  let Some(j) = parse_body(body) else { return Ok(bad); };
  let Some(m) = j.as_map() else { return Ok(bad); };
  if m.len() != 3 { return Ok(bad); }
  let Some(Json::Str(account)) = m.get("account") else { return Ok(bad); };
  if account == "" { return Ok(bad); }
  let Some(Json::Num(cents)) = m.get("cents") else { return Ok(bad); };
  if cents <= 0 { return Ok(bad); }
  let Some(Json::Str(currency)) = m.get("currency") else { return Ok(bad); };
  if currency != "EUR" && currency != "USD" { return Ok(bad); }
  let rows = db.query("INSERT INTO payments (account, cents, currency, status, refunded) VALUES (?, ?, ?, 'pending', 0) RETURNING " + COLS,
    [SqlValue::Text(account), SqlValue::Int(cents), SqlValue::Text(currency)])?;
  if rows.len() == 0 { return Ok(err(500, "internal error")); }
  Ok(ok_payment(201, rows[0]))
}

fn refund(db: Db, id: Int, body: Bytes) -> Result<Resp, DbErr> {
  let Some(p) = load(db, id)? else { return Ok(nf()); };
  let amount = match parse_body(body) {
    Some(j) => match j.get("cents") { Some(Json::Num(n)) => n, _ => 0 },
    None => 0,
  };
  if amount <= 0 { return Ok(err(422, "invalid refund")); }
  if str_of(p[4]) != "captured" { return Ok(err(409, "invalid transition")); }
  if amount > int_of(p[2]) - int_of(p[5]) { return Ok(err(409, "exceeds captured")); }
  let rows = db.query("UPDATE payments SET refunded = refunded + ?, status = CASE WHEN refunded + ? = cents THEN 'refunded' ELSE status END WHERE id = ? AND status = 'captured' AND refunded + ? <= cents RETURNING " + COLS,
    [SqlValue::Int(amount), SqlValue::Int(amount), SqlValue::Int(id), SqlValue::Int(amount)])?;
  if rows.len() == 0 {
    let Some(q) = load(db, id)? else { return Ok(nf()); };
    if str_of(q[4]) != "captured" { return Ok(err(409, "invalid transition")); }
    return Ok(err(409, "exceeds captured"));
  }
  Ok(ok_payment(200, rows[0]))
}

fn transition(db: Db, id: Int, capture: Bool) -> Result<Resp, DbErr> {
  let sql = if capture {
    "UPDATE payments SET status = 'captured' WHERE id = ? AND status IN ('pending', 'captured') RETURNING " + COLS
  } else {
    "UPDATE payments SET status = 'canceled' WHERE id = ? AND status = 'pending' RETURNING " + COLS
  };
  let rows = db.query(sql, [SqlValue::Int(id)])?;
  if rows.len() > 0 { return Ok(ok_payment(200, rows[0])); }
  match load(db, id)? {
    Some(_) => Ok(err(409, "invalid transition")),
    None => Ok(nf()),
  }
}

fn handle(req: Incoming, db: Db) -> Result<Resp, DbErr> {
  schema(db)?;
  let method = req.method();
  let target = req.target();
  let mut path = target;
  let mut query = "";
  if let Some(q) = target.find("?") {
    path = target.slice(0, q);
    query = target.slice(q + 1, target.len());
  }
  let segs = path.split("/");
  let n = segs.len();
  if n < 2 || segs[0] != "" || segs[1] != "payments" { return Ok(nf()); }

  if method == "POST" && (n == 2 || (n == 4 && segs[3] == "refund")) {
    let key = header(req, "idempotency-key").unwrap_or("");
    if key == "" { return Ok(err(400, "missing idempotency key")); }
    let body = req.body();
    let c = canon(body);
    let prev = db.query("SELECT method, path, body, status, resp FROM idem WHERE k = ?", [SqlValue::Text(key)])?;
    if prev.len() > 0 {
      let p = prev[0];
      if str_of(p[0]) == method && str_of(p[1]) == path && str_of(p[2]) == c {
        return Ok(Resp { status: int_of(p[3]), body: str_of(p[4]) });
      }
      return Ok(err(409, "key reused"));
    }
    let r = if n == 2 {
      create(db, body)?
    } else {
      match parse_id(segs[2]) {
        Some(id) => refund(db, id, body)?,
        None => nf(),
      }
    };
    if r.status >= 200 && r.status < 300 {
      db.exec("INSERT OR IGNORE INTO idem (k, method, path, body, status, resp) VALUES (?, ?, ?, ?, ?, ?)",
        [SqlValue::Text(key), SqlValue::Text(method), SqlValue::Text(path), SqlValue::Text(c), SqlValue::Int(r.status), SqlValue::Text(r.body)])?;
    }
    return Ok(r);
  }

  if method == "POST" && n == 4 && (segs[3] == "capture" || segs[3] == "cancel") {
    let Some(id) = parse_id(segs[2]) else { return Ok(nf()); };
    return transition(db, id, segs[3] == "capture");
  }

  if method == "GET" && n == 2 {
    let rows: List<List<SqlValue>> = match query_param(query, "account") {
      Some(a) => db.query("SELECT " + COLS + " FROM payments WHERE account = ? ORDER BY id", [SqlValue::Text(a)])?,
      None => [],
    };
    return Ok(Resp { status: 200, body: Json::Arr(rows.map(row_json)).to_json() });
  }

  if method == "GET" && n == 3 {
    let Some(id) = parse_id(segs[2]) else { return Ok(nf()); };
    return match load(db, id)? {
      Some(p) => Ok(ok_payment(200, p)),
      None => Ok(nf()),
    };
  }

  Ok(nf())
}

fn main(req: Incoming, res: Outgoing, db: Db) -> Str {
  let r = match handle(req, db) {
    Ok(r) => r,
    Err(_) => err(500, "internal error"),
  };
  match res.send(r.status, ["content-type"], ["application/json"], r.body.to_bytes()) {
    Ok(_) => r.status.to_str(),
    Err(_) => "send failed",
  }
}

struct UserData { times: List<Int>, pages: Map<Str, Bool> }

fn digits(b: Bytes, start: Int, n: Int) -> Option<Int> {
  let mut v = 0;
  for i in start..start + n {
    let c = b[i];
    if c < 48 || c > 57 { return None; }
    v = v * 10 + (c - 48);
  }
  Some(v)
}

fn is_leap(y: Int) -> Bool {
  (y % 4 == 0 && y % 100 != 0) || y % 400 == 0
}

fn days_in_month(y: Int, m: Int) -> Int {
  if m == 2 {
    if is_leap(y) { 29 } else { 28 }
  } else if m == 4 || m == 6 || m == 9 || m == 11 {
    30
  } else {
    31
  }
}

fn days_from_civil(y0: Int, m: Int, d: Int) -> Int {
  let y = if m <= 2 { y0 - 1 } else { y0 };
  let era = if y >= 0 { y / 400 } else { (y - 399) / 400 };
  let yoe = y - era * 400;
  let mp = if m > 2 { m - 3 } else { m + 9 };
  let doy = (153 * mp + 2) / 5 + d - 1;
  let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
  era * 146097 + doe - 719468
}

fn parse_time(s: Str) -> Option<Int> {
  let b = s.to_bytes();
  if b.len() != 20 { return None; }
  if b[4] != 45 || b[7] != 45 || b[10] != 84 || b[13] != 58 || b[16] != 58 || b[19] != 90 {
    return None;
  }
  let y = digits(b, 0, 4)?;
  let mo = digits(b, 5, 2)?;
  let d = digits(b, 8, 2)?;
  let h = digits(b, 11, 2)?;
  let mi = digits(b, 14, 2)?;
  let se = digits(b, 17, 2)?;
  if mo < 1 || mo > 12 { return None; }
  if d < 1 || d > days_in_month(y, mo) { return None; }
  if h > 23 || mi > 59 || se > 59 { return None; }
  Some(days_from_civil(y, mo, d) * 86400 + h * 3600 + mi * 60 + se)
}

fn pad2(n: Int) -> Str {
  if n < 10 { "0" + n.to_str() } else { n.to_str() }
}

fn hms(secs: Int) -> Str {
  pad2(secs / 3600) + ":" + pad2((secs % 3600) / 60) + ":" + pad2(secs % 60)
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("events.log")?.to_str();
  let mut malformed = 0;
  let mut duplicates = 0;
  let mut seen: HashMap<Str, Bool> = HashMap::new();
  let mut users: Map<Str, UserData> = Map::new();
  let mut page_counts: Map<Str, Int> = Map::new();
  let mut valid = 0;

  for line in text.lines() {
    if line.trim().len() == 0 { continue; }
    let parts = line.split(" ");
    if parts.len() != 3 || parts[0].len() == 0 || parts[1].len() == 0 || parts[2].len() == 0 {
      malformed += 1;
      continue;
    }
    let Some(t) = parse_time(parts[0]) else { malformed += 1; continue; };
    if seen.get(line).is_some() {
      duplicates += 1;
      continue;
    }
    seen.insert(line, true);
    valid += 1;
    let user = parts[1];
    let page = parts[2];
    let mut ud = users.get(user).unwrap_or(UserData { times: [], pages: Map::new() });
    ud.times.push(t);
    ud.pages.insert(page, true);
    users.insert(user, ud);
    let c = page_counts.get(page).unwrap_or(0);
    page_counts.insert(page, c + 1);
  }

  let last = "malformed " + malformed.to_str() + " duplicates " + duplicates.to_str();
  if valid == 0 { return Ok(last); }

  let mut out: List<Str> = [];
  let mut durations: List<Int> = [];
  for u in users.keys() {
    let Some(ud) = users.get(u) else { continue; };
    let mut ts = ud.times;
    ts.sort();
    let mut sessions = 0;
    let mut longest = 0;
    let mut start = ts[0];
    let mut prev = ts[0];
    for i in 1..ts.len() {
      let t = ts[i];
      if t - prev > 1800 {
        let dur = prev - start;
        durations.push(dur);
        sessions += 1;
        if dur > longest { longest = dur; }
        start = t;
      }
      prev = t;
    }
    let dur = prev - start;
    durations.push(dur);
    sessions += 1;
    if dur > longest { longest = dur; }
    out.push(u + " sessions " + sessions.to_str() + " events " + ts.len().to_str()
      + " longest " + hms(longest) + " pages " + ud.pages.len().to_str());
  }

  durations.sort();
  let med = durations[(durations.len() - 1) / 2];
  out.push("median " + med.to_str());

  let mut pages = page_counts.keys();
  let pc = page_counts;
  pages.sort_by(|a: Str, b: Str| {
    let ca = pc.get(a).unwrap_or(0);
    let cb = pc.get(b).unwrap_or(0);
    ca > cb || (ca == cb && a < b)
  });
  let mut tops: List<Str> = [];
  let n = pages.len().min(3);
  for i in 0..n {
    tops.push(pages[i] + " (" + pc.get(pages[i]).unwrap_or(0).to_str() + ")");
  }
  out.push("top: " + tops.join(", "));
  out.push(last);
  Ok(out.join("\n"))
}

struct Rec { fields: List<Str>, bad: Bool }

struct Agg { rev: Int, items: Int, prods: Map<Str, Int> }

fn parse(b: Bytes) -> List<Rec> {
  let n = b.len();
  let mut i = 0;
  let mut recs: List<Rec> = [];
  while i < n {
    if b[i] == 10 { i += 1; continue; }
    if b[i] == 13 && i + 1 < n && b[i + 1] == 10 { i += 2; continue; }
    let mut fields: List<Str> = [];
    let mut bad = false;
    loop {
      let mut buf = "".to_bytes();
      let mut raw = true;
      let mut eof_open = false;
      if i < n && b[i] == 34 {
        i += 1;
        let mut closed = false;
        while i < n {
          if b[i] == 34 {
            if i + 1 < n && b[i + 1] == 34 {
              buf.push(34);
              i += 2;
            } else {
              i += 1;
              closed = true;
              break;
            }
          } else {
            buf.push(b[i]);
            i += 1;
          }
        }
        if !closed {
          bad = true;
          eof_open = true;
        }
        raw = false;
        if !eof_open && i < n && b[i] != 44 && b[i] != 10 && !(b[i] == 13 && i + 1 < n && b[i + 1] == 10) {
          bad = true;
          raw = true;
        }
      }
      if eof_open {
        fields.push(buf.to_str());
        break;
      }
      if raw {
        while i < n {
          let c = b[i];
          if c == 44 || c == 10 { break; }
          if c == 13 && i + 1 < n && b[i + 1] == 10 { break; }
          if c == 34 { bad = true; }
          buf.push(c);
          i += 1;
        }
      }
      fields.push(buf.to_str());
      if i >= n { break; }
      if b[i] == 44 { i += 1; continue; }
      if b[i] == 10 { i += 1; break; }
      i += 2;
      break;
    }
    recs.push(Rec { fields: fields, bad: bad });
  }
  recs
}

fn digits(s: Str) -> Bool {
  if s.len() == 0 { return false; }
  for c in s.to_bytes() {
    if c < 48 || c > 57 { return false; }
  }
  true
}

fn price_cents(p: Str) -> Option<Int> {
  let parts = p.split(".");
  if parts.len() > 2 { return None; }
  if !digits(parts[0]) { return None; }
  let mut c = parts[0].parse_int()? * 100;
  if parts.len() == 2 {
    let f = parts[1];
    if !digits(f) || f.len() > 2 { return None; }
    let fv = f.parse_int()?;
    if f.len() == 1 { c = c + fv * 10; } else { c = c + fv; }
  }
  Some(c)
}

fn money(c: Int) -> Str {
  if c < 0 { return "-" + money(0 - c); }
  let f = c % 100;
  let pad = if f < 10 { "0" } else { "" };
  (c / 100).to_str() + "." + pad + f.to_str()
}

fn q(s: Str) -> Str {
  if s.contains(",") || s.contains("\"") || s.contains("\r") || s.contains("\n") {
    "\"" + s.replace("\"", "\"\"") + "\""
  } else {
    s
  }
}

fn main(input: Dir, out: Dir) -> Result<Str, IoErr> {
  let data = input.read("sales.csv")?;
  let recs = parse(data);
  let mut clean = "";
  let mut regions: Map<Str, Agg> = Map::new();
  let mut bads: List<Str> = [];
  let mut count = 0;
  let mut idx = 0;
  for r in recs {
    if idx == 0 {
      idx = 1;
      clean = clean + r.fields.map(|f| q(f)).join(",") + "\n";
      continue;
    }
    count += 1;
    let mut ok = !r.bad && r.fields.len() == 5;
    let mut qty = 0;
    let mut cents = 0;
    if ok {
      if r.fields[0] == "" || r.fields[1] == "" { ok = false; }
    }
    if ok {
      match r.fields[2].parse_int() {
        Some(v) => { qty = v; }
        None => { ok = false; }
      }
    }
    if ok {
      match price_cents(r.fields[3]) {
        Some(v) => { cents = v; }
        None => { ok = false; }
      }
    }
    if !ok {
      bads.push(count.to_str());
      continue;
    }
    let f = r.fields;
    let line: List<Str> = [q(f[0]), q(f[1]), q(f[2]), money(cents), q(f[4])];
    clean = clean + line.join(",") + "\n";
    let rev = qty * cents;
    let mut a = match regions.get(f[0]) {
      Some(a) => a,
      None => Agg { rev: 0, items: 0, prods: Map::new() },
    };
    a.rev = a.rev + rev;
    a.items = a.items + qty;
    let prev = a.prods.get(f[1]).unwrap_or(0);
    a.prods.insert(f[1], prev + rev);
    regions.insert(f[0], a);
  }
  out.write("clean.csv", clean.to_bytes())?;
  let mut lines: List<Str> = [];
  for name in regions.keys() {
    let Some(a) = regions.get(name) else { continue; };
    let mut top = "";
    let mut best = 0;
    let mut first = true;
    for p in a.prods.keys() {
      let v = a.prods.get(p).unwrap_or(0);
      if first || v > best {
        top = p;
        best = v;
        first = false;
      }
    }
    lines.push(name + " revenue " + money(a.rev) + " items " + a.items.to_str() + " top " + top);
  }
  if bads.len() == 0 {
    lines.push("records " + count.to_str() + " bad 0");
  } else {
    lines.push("records " + count.to_str() + " bad " + bads.len().to_str() + ": " + bads.join(", "));
  }
  Ok(lines.join("\n"))
}

fn kv_err(e: KvErr) -> Str {
  "kv error"
}

fn io_err(e: IoErr) -> Str {
  "io error"
}

fn is_word_byte(b: Int) -> Bool {
  b >= 128 || (b >= 48 && b <= 57) || (b >= 65 && b <= 90) || (b >= 97 && b <= 122)
}

fn words(text: Bytes) -> List<Str> {
  let mut out: List<Str> = [];
  let mut cur = "".to_bytes();
  for b in text {
    if is_word_byte(b) {
      cur.push(b);
    } else if cur.len() > 0 {
      out.push(cur.to_str().to_lowercase());
      cur = "".to_bytes();
    }
  }
  if cur.len() > 0 {
    out.push(cur.to_str().to_lowercase());
  }
  out
}

fn uniq_sorted(xs: List<Str>) -> List<Str> {
  let mut s = xs;
  s.sort();
  let mut out: List<Str> = [];
  for x in s {
    if out.len() == 0 || out[out.len() - 1] != x {
      out.push(x);
    }
  }
  out
}

fn walk(d: Dir, dir: Str, prefix: Str, acc: List<Str>) -> Result<List<Str>, IoErr> {
  let mut out = acc;
  let names = d.list(dir)?;
  for n in names {
    if let Some(sub) = n.strip_suffix("/") {
      let p = prefix + sub;
      out = walk(d, p, p + "/", out)?;
    } else {
      out.push(prefix + n);
    }
  }
  Ok(out)
}

fn list_to_json(xs: List<Str>) -> Str {
  Json::Arr(xs.map(|s| Json::Str(s))).to_json()
}

fn json_to_list(b: Bytes) -> List<Str> {
  let mut out: List<Str> = [];
  if let Ok(j) = b.to_str().parse_json() {
    if let Some(items) = j.as_list() {
      for it in items {
        if let Some(s) = it.as_str() {
          out.push(s);
        }
      }
    }
  }
  out
}

fn kv_list(index: Kv, key: Str) -> Result<List<Str>, Str> {
  match index.get(key).map_err(kv_err)? {
    Some(b) => Ok(json_to_list(b)),
    None => Ok([]),
  }
}

fn idx(index: Kv, t: HashMap<Str, List<Str>>, w: Str) -> Result<List<Str>, Str> {
  match t.get(w) {
    Some(l) => Ok(l),
    None => kv_list(index, "i:" + w),
  }
}

fn load_files(index: Kv) -> Result<Map<Str, Str>, Str> {
  let mut m: Map<Str, Str> = Map::new();
  if let Some(b) = index.get("files").map_err(kv_err)? {
    if let Ok(j) = b.to_str().parse_json() {
      if let Some(obj) = j.as_map() {
        for k in obj.keys() {
          if let Some(v) = obj.get(k) {
            if let Some(s) = v.as_str() {
              m.insert(k, s);
            }
          }
        }
      }
    }
  }
  Ok(m)
}

fn main(docs: Dir, queries: Dir, index: Kv) -> Result<Str, Str> {
  let mut paths = walk(docs, "", "", []).map_err(io_err)?;
  paths.sort();
  let old = load_files(index)?;

  let mut newm: Map<Str, Str> = Map::new();
  let mut t: HashMap<Str, List<Str>> = HashMap::new();
  let mut lines: List<Str> = [];
  let mut unchanged = 0;

  // all paths, current and removed
  let mut all = paths;
  for k in old.keys() {
    if newm.get(k).is_none() && !paths.contains(k) {
      all.push(k);
    }
  }
  all.sort();

  for p in all {
    let is_new = paths.contains(p);
    let old_hash = old.get(p);
    if is_new {
      let content = docs.read(p).map_err(io_err)?;
      let h = content.sha256().to_hex();
      newm.insert(p, h);
      let same = match old_hash {
        Some(oh) => oh == h,
        None => false,
      };
      if same {
        unchanged += 1;
        continue;
      }
      // remove old words if changed
      if old_hash.is_some() {
        let ow = kv_list(index, "w:" + p)?;
        for w in ow {
          let mut l = idx(index, t, w)?;
          l = l.filter(|x| x != p);
          t.insert(w, l);
        }
        lines.push("changed " + p);
      } else {
        lines.push("added " + p);
      }
      let nw = uniq_sorted(words(content));
      for w in nw {
        let mut l = idx(index, t, w)?;
        if !l.contains(p) {
          l.push(p);
          l.sort();
        }
        t.insert(w, l);
      }
      index.set("w:" + p, list_to_json(nw).to_bytes()).map_err(kv_err)?;
    } else {
      let ow = kv_list(index, "w:" + p)?;
      for w in ow {
        let mut l = idx(index, t, w)?;
        l = l.filter(|x| x != p);
        t.insert(w, l);
      }
      index.delete("w:" + p).map_err(kv_err)?;
      lines.push("removed " + p);
    }
  }

  for w in t.keys() {
    let l = t.get(w).unwrap_or([]);
    if l.len() == 0 {
      index.delete("i:" + w).map_err(kv_err)?;
    } else {
      index.set("i:" + w, list_to_json(l).to_bytes()).map_err(kv_err)?;
    }
  }

  let mut fobj: Map<Str, Json> = Map::new();
  for k in newm.keys() {
    fobj.insert(k, Json::Str(newm.get(k).unwrap_or("")));
  }
  index.set("files", Json::Obj(fobj).to_json().to_bytes()).map_err(kv_err)?;

  lines.push("unchanged " + unchanged.to_str());

  let qtext = queries.read("queries.txt").map_err(io_err)?.to_str();
  let empty: HashMap<Str, List<Str>> = HashMap::new();
  for line in qtext.lines() {
    if line.trim().len() == 0 {
      continue;
    }
    let ws = uniq_sorted(words(line.to_bytes()));
    let mut res: List<Str> = paths;
    for w in ws {
      let l = idx(index, empty, w)?;
      res = res.filter(|x| l.contains(x));
    }
    res.sort();
    if res.len() == 0 {
      lines.push(line + ": none");
    } else {
      lines.push(line + ": " + res.join(", "));
    }
  }

  Ok(lines.join("\n"))
}

struct Page { changes: List<Json>, next: Option<Str> }

enum Change { Upsert(Str, Str, Int, Int), Delete(Str, Int), Invalid }

fn de(e: DbErr) -> Str {
  match e {
    DbErr::Invalid(s) => "db invalid: " + s,
    DbErr::Denied => "db denied",
    DbErr::Busy => "db busy",
    DbErr::TooLarge => "db too large",
    DbErr::Constraint(s) => "db constraint: " + s,
  }
}

fn valid_utf8(b: Bytes) -> Bool {
  let n = b.len();
  let mut i = 0;
  while i < n {
    let c = b[i];
    if c < 128 { i += 1; continue; }
    let mut len = 0;
    let mut lo = 128;
    let mut hi = 191;
    if c >= 194 && c <= 223 { len = 2; }
    else if c == 224 { len = 3; lo = 160; }
    else if (c >= 225 && c <= 236) || c == 238 || c == 239 { len = 3; }
    else if c == 237 { len = 3; hi = 159; }
    else if c == 240 { len = 4; lo = 144; }
    else if c >= 241 && c <= 243 { len = 4; }
    else if c == 244 { len = 4; hi = 143; }
    else { return false; }
    if i + len > n { return false; }
    let b1 = b[i + 1];
    if b1 < lo || b1 > hi { return false; }
    let mut k = 2;
    while k < len {
      let bk = b[i + k];
      if bk < 128 || bk > 191 { return false; }
      k += 1;
    }
    i += len;
  }
  true
}

fn enc(s: Str) -> Str {
  let hex = "0123456789ABCDEF";
  let mut out = "";
  for c in s.to_bytes() {
    let unreserved = (c >= 65 && c <= 90) || (c >= 97 && c <= 122) || (c >= 48 && c <= 57)
      || c == 45 || c == 46 || c == 95 || c == 126;
    if unreserved {
      let mut one = "".to_bytes();
      one.push(c);
      out = out + one.to_str();
    } else {
      out = out + "%" + hex.slice(c / 16, c / 16 + 1) + hex.slice(c % 16, c % 16 + 1);
    }
  }
  out
}

fn parse_page(body: Bytes) -> Option<Page> {
  if !valid_utf8(body) { return None; }
  let doc = body.to_str().parse_json().ok()?;
  match doc {
    Json::Obj(m) => {
      let changes = match m.get("changes") {
        Some(Json::Arr(xs)) => xs,
        _ => { return None; }
      };
      let next: Option<Str> = match m.get("next") {
        None => None,
        Some(Json::Null) => None,
        Some(Json::Str(s)) => Some(s),
        Some(_) => { return None; }
      };
      Some(Page { changes: changes, next: next })
    }
    _ => None,
  }
}

fn parse_change(j: Json) -> Change {
  let Some(op) = j.get("op").and_then(|x| x.as_str()) else { return Change::Invalid; };
  let Some(sku) = j.get("sku").and_then(|x| x.as_str()) else { return Change::Invalid; };
  let Some(ver) = j.get("version").and_then(|x| x.as_int()) else { return Change::Invalid; };
  if op == "upsert" {
    let Some(name) = j.get("name").and_then(|x| x.as_str()) else { return Change::Invalid; };
    let Some(qty) = j.get("qty").and_then(|x| x.as_int()) else { return Change::Invalid; };
    Change::Upsert(sku, name, qty, ver)
  } else if op == "delete" {
    Change::Delete(sku, ver)
  } else {
    Change::Invalid
  }
}

fn lookup(db: Db, m: Map<Str, Int>, sku: Str) -> Result<Option<Int>, Str> {
  if let Some(v) = m.get(sku) { return Ok(Some(v)); }
  let rows = db.query("SELECT version FROM versions WHERE sku = ?", [SqlValue::Text(sku)]).map_err(de)?;
  if rows.len() == 0 { return Ok(None); }
  let row = rows[0];
  if row.len() == 0 { return Ok(None); }
  match row[0] {
    SqlValue::Int(v) => Ok(Some(v)),
    _ => Ok(None),
  }
}

fn load_cursor(db: Db) -> Result<Str, Str> {
  let rows = db.query("SELECT v FROM state WHERE k = 'cursor'", []).map_err(de)?;
  if rows.len() == 0 { return Ok("0"); }
  let row = rows[0];
  if row.len() == 0 { return Ok("0"); }
  match row[0] {
    SqlValue::Text(s) => Ok(s),
    _ => Ok("0"),
  }
}

fn val_str(v: SqlValue) -> Str {
  match v {
    SqlValue::Null => "",
    SqlValue::Int(i) => i.to_str(),
    SqlValue::Float(f) => f.to_str(),
    SqlValue::Text(s) => s,
    SqlValue::Blob(b) => b.to_hex(),
  }
}

fn main(api: Http, db: Db) -> Result<Str, Str> {
  db.exec("CREATE TABLE IF NOT EXISTS items (sku TEXT PRIMARY KEY, name TEXT NOT NULL, qty INTEGER NOT NULL)", []).map_err(de)?;
  db.exec("CREATE TABLE IF NOT EXISTS versions (sku TEXT PRIMARY KEY, version INTEGER NOT NULL)", []).map_err(de)?;
  db.exec("CREATE TABLE IF NOT EXISTS state (k TEXT PRIMARY KEY, v TEXT NOT NULL)", []).map_err(de)?;

  let mut cursor = load_cursor(db)?;
  let mut versions: Map<Str, Int> = Map::new();
  let mut pages = 0;
  let mut applied = 0;
  let mut stale = 0;
  let mut invalid = 0;
  let mut status_line = "";

  loop {
    let path = "/changes?cursor=" + enc(cursor);
    let resp = match api.send("GET", path, [], "".to_bytes()) {
      Ok(r) => r,
      Err(_) => {
        status_line = "stopped at " + cursor + " (no response)";
        break;
      }
    };
    if resp.status != 200 {
      status_line = "stopped at " + cursor + " (status " + resp.status.to_str() + ")";
      break;
    }
    let Some(page) = parse_page(resp.body) else {
      status_line = "stopped at " + cursor + " (invalid page)";
      break;
    };

    let mut local = versions;
    let mut stmts: List<Str> = [];
    let mut params: List<List<SqlValue>> = [];
    let mut a = 0;
    let mut s = 0;
    let mut inv = 0;
    for cj in page.changes {
      match parse_change(cj) {
        Change::Invalid => { inv += 1; }
        Change::Upsert(sku, name, qty, ver) => {
          let old = lookup(db, local, sku)?;
          let is_stale = match old { Some(o) => ver <= o, None => false };
          if is_stale {
            s += 1;
          } else {
            a += 1;
            local.insert(sku, ver);
            stmts.push("INSERT OR REPLACE INTO items (sku, name, qty) VALUES (?, ?, ?)");
            params.push([SqlValue::Text(sku), SqlValue::Text(name), SqlValue::Int(qty)]);
            stmts.push("INSERT OR REPLACE INTO versions (sku, version) VALUES (?, ?)");
            params.push([SqlValue::Text(sku), SqlValue::Int(ver)]);
          }
        }
        Change::Delete(sku, ver) => {
          let old = lookup(db, local, sku)?;
          let is_stale = match old { Some(o) => ver <= o, None => false };
          if is_stale {
            s += 1;
          } else {
            a += 1;
            local.insert(sku, ver);
            stmts.push("DELETE FROM items WHERE sku = ?");
            params.push([SqlValue::Text(sku)]);
            stmts.push("INSERT OR REPLACE INTO versions (sku, version) VALUES (?, ?)");
            params.push([SqlValue::Text(sku), SqlValue::Int(ver)]);
          }
        }
      }
    }
    if let Some(n) = page.next {
      stmts.push("INSERT OR REPLACE INTO state (k, v) VALUES ('cursor', ?)");
      params.push([SqlValue::Text(n)]);
    }
    if stmts.len() > 0 {
      db.transaction(stmts, params).map_err(de)?;
    }
    versions = local;
    pages += 1;
    applied += a;
    stale += s;
    invalid += inv;
    match page.next {
      Some(n) => { cursor = n; }
      None => {
        status_line = "complete";
        break;
      }
    }
  }

  let mut out = "pages " + pages.to_str() + " applied " + applied.to_str() + " stale " + stale.to_str()
    + " invalid " + invalid.to_str() + "\n" + status_line;
  let rows = db.query("SELECT sku, qty, name FROM items ORDER BY sku", []).map_err(de)?;
  for row in rows {
    if row.len() < 3 { continue; }
    out = out + "\n" + val_str(row[0]) + " " + val_str(row[1]) + " " + val_str(row[2]);
  }
  Ok(out)
}

struct Job { id: Str, priority: Int, due: Int, attempts: Int, state: Str }

fn job_to_json(j: Job) -> Json {
  let mut m: Map<Str, Json> = Map::new();
  m.insert("priority", Json::Num(j.priority));
  m.insert("due", Json::Num(j.due));
  m.insert("attempts", Json::Num(j.attempts));
  m.insert("state", Json::Str(j.state));
  Json::Obj(m)
}

fn json_to_job(id: Str, j: Json) -> Option<Job> {
  let priority = j.get("priority")?.as_int()?;
  let due = j.get("due")?.as_int()?;
  let attempts = j.get("attempts")?.as_int()?;
  let state = j.get("state")?.as_str()?;
  Some(Job { id: id, priority: priority, due: due, attempts: attempts, state: state })
}

fn load(queue: Kv) -> Result<Map<Str, Job>, Str> {
  let mut jobs: Map<Str, Job> = Map::new();
  match queue.get("jobs") {
    Err(_) => { return Err("kv error"); }
    Ok(None) => {}
    Ok(Some(b)) => {
      let doc = b.to_str().parse_json()?;
      let m = doc.as_map().unwrap_or(Map::new());
      for k in m.keys() {
        let Some(v) = m.get(k) else { continue; };
        if let Some(j) = json_to_job(k, v) {
          jobs.insert(k, j);
        }
      }
    }
  }
  Ok(jobs)
}

fn save(queue: Kv, jobs: Map<Str, Job>) -> Result<(), Str> {
  let mut m: Map<Str, Json> = Map::new();
  for k in jobs.keys() {
    let Some(j) = jobs.get(k) else { continue; };
    m.insert(k, job_to_json(j));
  }
  match queue.set("jobs", Json::Obj(m).to_json().to_bytes()) {
    Ok(()) => Ok(()),
    Err(_) => Err("kv error"),
  }
}

fn read_opt(d: Dir, name: Str) -> Result<Str, Str> {
  match d.read(name) {
    Ok(b) => Ok(b.to_str()),
    Err(IoErr::NotFound) => Ok(""),
    Err(_) => Err("cannot read " + name),
  }
}

fn parse_job(line: Str, now: Int) -> Option<Job> {
  let j = line.trim().parse_json().ok()?;
  let m = j.as_map()?;
  let id = m.get("id")?.as_str()?;
  let priority = m.get("priority")?.as_int()?;
  Some(Job { id: id, priority: priority, due: now, attempts: 0, state: "pending" })
}

fn parse_script(text: Str) -> Map<Str, List<Str>> {
  let mut out: Map<Str, List<Str>> = Map::new();
  if text.trim().len() == 0 { return out; }
  let Ok(doc) = text.parse_json() else { return out; };
  let Some(m) = doc.as_map() else { return out; };
  for k in m.keys() {
    let Some(v) = m.get(k) else { continue; };
    let Some(l) = v.as_list() else { continue; };
    let mut outs: List<Str> = [];
    for e in l {
      outs.push(e.as_str().unwrap_or("ok"));
    }
    out.insert(k, outs);
  }
  out
}

fn less(a: Job, b: Job) -> Bool {
  if a.priority != b.priority {
    a.priority > b.priority
  } else if a.due != b.due {
    a.due < b.due
  } else {
    a.id < b.id
  }
}

fn main(input: Dir, queue: Kv, clock: Clock) -> Result<Str, Str> {
  let now = clock.now_ms();
  let mut jobs = load(queue)?;
  let mut out: List<Str> = [];

  let text = read_opt(input, "enqueue.jsonl")?;
  let lines = text.lines();
  for i in 0..lines.len() {
    let line = lines[i];
    if line.trim().len() == 0 { continue; }
    let Some(p) = parse_job(line, now) else {
      out.push("invalid line " + (i + 1).to_str());
      continue;
    };
    if jobs.get(p.id).is_some() {
      out.push("duplicate " + p.id);
    } else {
      jobs.insert(p.id, p);
    }
  }

  let script = parse_script(read_opt(input, "script.json")?);

  let mut due: List<Job> = [];
  for k in jobs.keys() {
    let Some(j) = jobs.get(k) else { continue; };
    if j.state == "pending" && j.due <= now {
      due.push(j);
    }
  }
  due.sort_by(less);
  let n = due.len().min(5);
  for i in 0..n {
    let mut j = due[i];
    let k = j.attempts + 1;
    j.attempts = k;
    let outcome = match script.get(j.id) {
      Some(l) => {
        if l.len() == 0 { "ok" } else { l[(k - 1).min(l.len() - 1)] }
      }
      None => "ok",
    };
    if outcome == "fail" {
      if k >= 4 {
        j.state = "dead";
        out.push("dead " + j.id);
      } else {
        let mut s = 60;
        let mut t = 1;
        while t < k {
          s = s * 2;
          t = t + 1;
        }
        j.due = now + s * 1000;
        out.push("retry " + j.id + " in " + s.to_str());
      }
    } else {
      j.state = "done";
      out.push("done " + j.id);
    }
    jobs.insert(j.id, j);
  }

  let mut p = 0;
  let mut d = 0;
  let mut x = 0;
  for k in jobs.keys() {
    let Some(j) = jobs.get(k) else { continue; };
    if j.state == "pending" { p = p + 1; }
    else if j.state == "done" { d = d + 1; }
    else { x = x + 1; }
  }
  out.push("pending " + p.to_str() + " done " + d.to_str() + " dead " + x.to_str());

  save(queue, jobs)?;
  Ok(out.join("\n"))
}

struct Job { id: Str, priority: Int, due: Int, attempts: Int, state: Str }

fn job_to_json(j: Job) -> Json {
  let mut m: Map<Str, Json> = Map::new();
  m.insert("priority", Json::Num(j.priority));
  m.insert("due", Json::Num(j.due));
  m.insert("attempts", Json::Num(j.attempts));
  m.insert("state", Json::Str(j.state));
  Json::Obj(m)
}

fn json_to_job(id: Str, j: Json) -> Option<Job> {
  let priority = j.get("priority")?.as_int()?;
  let due = j.get("due")?.as_int()?;
  let attempts = j.get("attempts")?.as_int()?;
  let state = j.get("state")?.as_str()?;
  Some(Job { id: id, priority: priority, due: due, attempts: attempts, state: state })
}

fn load(queue: Kv) -> Result<Map<Str, Job>, Str> {
  let mut jobs: Map<Str, Job> = Map::new();
  match queue.get("jobs") {
    Err(_) => { return Err("kv error"); }
    Ok(None) => {}
    Ok(Some(b)) => {
      let doc = b.to_str().parse_json()?;
      let m = doc.as_map().unwrap_or(Map::new());
      for k in m.keys() {
        let Some(v) = m.get(k) else { continue; };
        if let Some(j) = json_to_job(k, v) {
          jobs.insert(k, j);
        }
      }
    }
  }
  Ok(jobs)
}

fn save(queue: Kv, jobs: Map<Str, Job>) -> Result<Bool, Str> {
  let mut m: Map<Str, Json> = Map::new();
  for k in jobs.keys() {
    let Some(j) = jobs.get(k) else { continue; };
    m.insert(k, job_to_json(j));
  }
  match queue.set("jobs", Json::Obj(m).to_json().to_bytes()) {
    Ok(_) => Ok(true),
    Err(_) => Err("kv error"),
  }
}

fn read_opt(d: Dir, name: Str) -> Result<Str, Str> {
  match d.read(name) {
    Ok(b) => Ok(b.to_str()),
    Err(IoErr::NotFound) => Ok(""),
    Err(_) => Err("cannot read " + name),
  }
}

fn parse_job(line: Str, now: Int) -> Option<Job> {
  let j = line.trim().parse_json().ok()?;
  let m = j.as_map()?;
  let id = m.get("id")?.as_str()?;
  let priority = m.get("priority")?.as_int()?;
  Some(Job { id: id, priority: priority, due: now, attempts: 0, state: "pending" })
}

fn parse_script(text: Str) -> Map<Str, List<Str>> {
  let mut out: Map<Str, List<Str>> = Map::new();
  if text.trim().len() == 0 { return out; }
  let Ok(doc) = text.parse_json() else { return out; };
  let Some(m) = doc.as_map() else { return out; };
  for k in m.keys() {
    let Some(v) = m.get(k) else { continue; };
    let Some(l) = v.as_list() else { continue; };
    let mut outs: List<Str> = [];
    for e in l {
      outs.push(e.as_str().unwrap_or("ok"));
    }
    out.insert(k, outs);
  }
  out
}

fn less(a: Job, b: Job) -> Bool {
  if a.priority != b.priority {
    a.priority > b.priority
  } else if a.due != b.due {
    a.due < b.due
  } else {
    a.id < b.id
  }
}

fn main(input: Dir, queue: Kv, clock: Clock) -> Result<Str, Str> {
  let now = clock.now_ms();
  let mut jobs = load(queue)?;
  let mut out: List<Str> = [];

  let text = read_opt(input, "enqueue.jsonl")?;
  let lines = text.lines();
  for i in 0..lines.len() {
    let line = lines[i];
    if line.trim().len() == 0 { continue; }
    let Some(p) = parse_job(line, now) else {
      out.push("invalid line " + (i + 1).to_str());
      continue;
    };
    if jobs.get(p.id).is_some() {
      out.push("duplicate " + p.id);
    } else {
      jobs.insert(p.id, p);
    }
  }

  let script = parse_script(read_opt(input, "script.json")?);

  let mut due: List<Job> = [];
  for k in jobs.keys() {
    let Some(j) = jobs.get(k) else { continue; };
    if j.state == "pending" && j.due <= now {
      due.push(j);
    }
  }
  due.sort_by(less);
  let n = due.len().min(5);
  for i in 0..n {
    let mut j = due[i];
    let k = j.attempts + 1;
    j.attempts = k;
    let outcome = match script.get(j.id) {
      Some(l) => {
        if l.len() == 0 { "ok" } else { l[(k - 1).min(l.len() - 1)] }
      }
      None => "ok",
    };
    if outcome == "fail" {
      if k >= 4 {
        j.state = "dead";
        out.push("dead " + j.id);
      } else {
        let mut s = 60;
        let mut t = 1;
        while t < k {
          s = s * 2;
          t = t + 1;
        }
        j.due = now + s * 1000;
        out.push("retry " + j.id + " in " + s.to_str());
      }
    } else {
      j.state = "done";
      out.push("done " + j.id);
    }
    jobs.insert(j.id, j);
  }

  let mut p = 0;
  let mut d = 0;
  let mut x = 0;
  for k in jobs.keys() {
    let Some(j) = jobs.get(k) else { continue; };
    if j.state == "pending" { p = p + 1; }
    else if j.state == "done" { d = d + 1; }
    else { x = x + 1; }
  }
  out.push("pending " + p.to_str() + " done " + d.to_str() + " dead " + x.to_str());

  save(queue, jobs)?;
  Ok(out.join("\n"))
}

enum Tok { Num(Str), Name(Str), Op(Str) }

enum Expr { Num(Str), Var(Str), Neg(List<Expr>), Bin(Str, List<Expr>), Call(Str, List<Expr>) }

struct PR { e: Expr, pos: Int }

struct Stmt { is_let: Bool, name: Str, e: Expr }

const MAXI: Int = 9223372036854775807;

fn min_int() -> Int { 0 - MAXI - 1 }

fn is_digit(c: Int) -> Bool { c >= 48 && c <= 57 }

fn is_alpha(c: Int) -> Bool { (c >= 65 && c <= 90) || (c >= 97 && c <= 122) || c == 95 }

fn tokenize(s: Str) -> Option<List<Tok>> {
  let b = s.to_bytes();
  let n = b.len();
  let mut i = 0;
  let mut out: List<Tok> = [];
  while i < n {
    let c = b[i];
    if c == 32 { i += 1; continue; }
    if is_digit(c) {
      let st = i;
      while i < n && is_digit(b[i]) { i += 1; }
      out.push(Tok::Num(s.slice(st, i)));
      continue;
    }
    if is_alpha(c) {
      let st = i;
      while i < n && (is_alpha(b[i]) || is_digit(b[i])) { i += 1; }
      out.push(Tok::Name(s.slice(st, i)));
      continue;
    }
    if c >= 128 { return None; }
    let ch = s.slice(i, i + 1);
    if "+-*/%^(),=".contains(ch) {
      out.push(Tok::Op(ch));
      i += 1;
    } else {
      return None;
    }
  }
  Some(out)
}

fn op_at(t: List<Tok>, p: Int) -> Str {
  if p >= t.len() { return ""; }
  match t[p] {
    Tok::Op(o) => o,
    _ => "",
  }
}

fn parse_expr(t: List<Tok>, p: Int) -> Option<PR> {
  let mut r = parse_term(t, p)?;
  loop {
    let o = op_at(t, r.pos);
    if o == "+" || o == "-" {
      let r2 = parse_term(t, r.pos + 1)?;
      r = PR { e: Expr::Bin(o, [r.e, r2.e]), pos: r2.pos };
    } else {
      break;
    }
  }
  Some(r)
}

fn parse_term(t: List<Tok>, p: Int) -> Option<PR> {
  let mut r = parse_factor(t, p)?;
  loop {
    let o = op_at(t, r.pos);
    if o == "*" || o == "/" || o == "%" {
      let r2 = parse_factor(t, r.pos + 1)?;
      r = PR { e: Expr::Bin(o, [r.e, r2.e]), pos: r2.pos };
    } else {
      break;
    }
  }
  Some(r)
}

fn parse_factor(t: List<Tok>, p: Int) -> Option<PR> {
  if op_at(t, p) == "-" {
    let r = parse_factor(t, p + 1)?;
    return Some(PR { e: Expr::Neg([r.e]), pos: r.pos });
  }
  parse_power(t, p)
}

fn parse_power(t: List<Tok>, p: Int) -> Option<PR> {
  let r = parse_atom(t, p)?;
  if op_at(t, r.pos) == "^" {
    let r2 = parse_factor(t, r.pos + 1)?;
    return Some(PR { e: Expr::Bin("^", [r.e, r2.e]), pos: r2.pos });
  }
  Some(r)
}

fn parse_atom(t: List<Tok>, p: Int) -> Option<PR> {
  if p >= t.len() { return None; }
  match t[p] {
    Tok::Num(s) => Some(PR { e: Expr::Num(s), pos: p + 1 }),
    Tok::Name(n) => {
      if op_at(t, p + 1) == "(" {
        let mut args: List<Expr> = [];
        let r = parse_expr(t, p + 2)?;
        args.push(r.e);
        let mut q = r.pos;
        while op_at(t, q) == "," {
          let r2 = parse_expr(t, q + 1)?;
          args.push(r2.e);
          q = r2.pos;
        }
        if op_at(t, q) != ")" { return None; }
        Some(PR { e: Expr::Call(n, args), pos: q + 1 })
      } else {
        Some(PR { e: Expr::Var(n), pos: p + 1 })
      }
    }
    Tok::Op(o) => {
      if o != "(" { return None; }
      let r = parse_expr(t, p + 1)?;
      if op_at(t, r.pos) != ")" { return None; }
      Some(PR { e: r.e, pos: r.pos + 1 })
    }
  }
}

fn parse_line(line: Str) -> Option<Stmt> {
  let t = tokenize(line)?;
  if t.len() > 0 && t[0] == Tok::Name("let") {
    if t.len() < 3 { return None; }
    let Tok::Name(n) = t[1] else { return None; };
    if op_at(t, 2) != "=" { return None; }
    let r = parse_expr(t, 3)?;
    if r.pos != t.len() { return None; }
    return Some(Stmt { is_let: true, name: n, e: r.e });
  }
  let r = parse_expr(t, 0)?;
  if r.pos != t.len() { return None; }
  Some(Stmt { is_let: false, name: "", e: r.e })
}

fn add(a: Int, b: Int) -> Result<Int, Str> {
  if b > 0 && a > MAXI - b { return Err("overflow"); }
  if b < 0 && a < min_int() - b { return Err("overflow"); }
  Ok(a + b)
}

fn sub(a: Int, b: Int) -> Result<Int, Str> {
  if b < 0 && a > MAXI + b { return Err("overflow"); }
  if b > 0 && a < min_int() + b { return Err("overflow"); }
  Ok(a - b)
}

fn mul(a: Int, b: Int) -> Result<Int, Str> {
  if a == 0 || b == 0 { return Ok(0); }
  let bad = if a > 0 {
    if b > 0 { a > MAXI / b } else { b < min_int() / a }
  } else {
    if b > 0 { a < min_int() / b } else { a < MAXI / b }
  };
  if bad { return Err("overflow"); }
  Ok(a * b)
}

fn pow(a: Int, b: Int) -> Result<Int, Str> {
  if b < 0 { return Err("negative exponent"); }
  let mut r = 1;
  let mut base = a;
  let mut e = b;
  loop {
    if e % 2 == 1 { r = mul(r, base)?; }
    e = e / 2;
    if e == 0 { break; }
    base = mul(base, base)?;
  }
  Ok(r)
}

fn eval(e: Expr, env: Map<Str, Int>) -> Result<Int, Str> {
  match e {
    Expr::Num(s) => s.parse_int().ok_or("overflow"),
    Expr::Var(n) => env.get(n).ok_or("unknown variable " + n),
    Expr::Neg(xs) => {
      let v = eval(xs[0], env)?;
      if v == min_int() { return Err("overflow"); }
      Ok(0 - v)
    }
    Expr::Bin(o, xs) => {
      let a = eval(xs[0], env)?;
      let b = eval(xs[1], env)?;
      match o {
        "+" => add(a, b),
        "-" => sub(a, b),
        "*" => mul(a, b),
        "/" => {
          if b == 0 { return Err("division by zero"); }
          if a == min_int() && b == -1 { return Err("overflow"); }
          Ok(a / b)
        }
        "%" => {
          if b == 0 { return Err("division by zero"); }
          if b == -1 { return Ok(0); }
          Ok(a % b)
        }
        _ => pow(a, b),
      }
    }
    Expr::Call(n, args) => {
      let want = if n == "min" || n == "max" { 2 } else if n == "abs" { 1 } else { 0 };
      if want == 0 { return Err("unknown function " + n); }
      if args.len() != want { return Err("wrong number of arguments to " + n); }
      let mut vals: List<Int> = [];
      for a in args { vals.push(eval(a, env)?); }
      if n == "min" { return Ok(vals[0].min(vals[1])); }
      if n == "max" { return Ok(vals[0].max(vals[1])); }
      if vals[0] == min_int() { return Err("overflow"); }
      if vals[0] < 0 { Ok(0 - vals[0]) } else { Ok(vals[0]) }
    }
  }
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("program.txt")?.to_str();
  let mut env: Map<Str, Int> = Map::new();
  let mut out: List<Str> = [];
  let mut ln = 0;
  for line in text.lines() {
    ln += 1;
    if line.trim() == "" { continue; }
    let pre = ln.to_str() + ": ";
    match parse_line(line) {
      None => out.push(pre + "error: syntax error"),
      Some(st) => {
        match eval(st.e, env) {
          Ok(v) => {
            if st.is_let {
              env.insert(st.name, v);
              out.push(pre + st.name + " = " + v.to_str());
            } else {
              out.push(pre + v.to_str());
            }
          }
          Err(m) => out.push(pre + "error: " + m),
        }
      }
    }
  }
  Ok(out.join("\n"))
}

struct Resp { status: Int, body: Str }

struct Event { id: Str, kind: Str, sub: Str, seq: Int }

struct Sub { exists: Bool, state: Str, last: Int, hist: List<Str> }

fn obj1(k: Str, v: Str) -> Str {
  let mut m: Map<Str, Json> = Map::new();
  m.insert(k, Json::Str(v));
  Json::Obj(m).to_json()
}

fn resp(status: Int, body: Str) -> Resp { Resp { status: status, body: body } }

fn not_found() -> Resp { resp(404, obj1("error", "not found")) }

fn status_resp(code: Int, s: Str) -> Resp { resp(code, obj1("status", s)) }

fn logw(log: Log, s: Str) {
  match log.write(s) { Ok(_) => {}, Err(_) => {} }
}

fn sv_int(v: SqlValue) -> Int { match v { SqlValue::Int(n) => n, _ => 0 } }
fn sv_str(v: SqlValue) -> Str { match v { SqlValue::Text(s) => s, _ => "" } }

fn valid_utf8(b: Bytes) -> Bool {
  let n = b.len();
  let mut i = 0;
  while i < n {
    let c = b[i];
    if c < 128 { i += 1; continue; }
    let mut need = 0;
    let mut min = 0;
    let mut cp = 0;
    if c >= 194 && c <= 223 { need = 1; min = 128; cp = c - 192; }
    else if c >= 224 && c <= 239 { need = 2; min = 2048; cp = c - 224; }
    else if c >= 240 && c <= 244 { need = 3; min = 65536; cp = c - 240; }
    else { return false; }
    if i + need >= n { return false; }
    for k in 1..need + 1 {
      let d = b[i + k];
      if d < 128 || d > 191 { return false; }
      cp = cp * 64 + (d - 128);
    }
    if cp < min || cp > 1114111 || (cp >= 55296 && cp <= 57343) { return false; }
    i += need + 1;
  }
  true
}

fn str_field(m: Map<Str, Json>, k: Str) -> Option<Str> {
  match m.get(k) { Some(Json::Str(s)) => Some(s), _ => None }
}

fn parse_event(body: Bytes) -> Option<Event> {
  if !valid_utf8(body) { return None; }
  let doc = body.to_str().parse_json().ok()?;
  let Json::Obj(m) = doc else { return None; };
  let id = str_field(m, "id")?;
  let kind = str_field(m, "type")?;
  let sub = str_field(m, "subscription")?;
  let seq = match m.get("seq") { Some(Json::Num(n)) => n, _ => return None };
  if seq < 1 { return None; }
  let kinds = ["subscription.created", "subscription.activated", "payment.failed", "subscription.canceled"];
  if !kinds.contains(kind) { return None; }
  Some(Event { id: id, kind: kind, sub: sub, seq: seq })
}

fn next_state(state: Str, kind: Str) -> Option<Str> {
  if kind == "subscription.created" {
    if state == "none" { return Some("created"); }
  } else if kind == "subscription.activated" {
    if state == "created" || state == "past_due" { return Some("active"); }
  } else if kind == "payment.failed" {
    if state == "active" { return Some("past_due"); }
  } else if kind == "subscription.canceled" {
    if state == "created" || state == "active" || state == "past_due" { return Some("canceled"); }
  }
  None
}

fn parse_hist(t: Str) -> List<Str> {
  let mut out: List<Str> = [];
  match t.parse_json() {
    Ok(Json::Arr(xs)) => { for x in xs { if let Json::Str(s) = x { out.push(s); } } },
    _ => {}
  }
  out
}

fn hist_json(h: List<Str>) -> Json { Json::Arr(h.map(|s| Json::Str(s))) }

fn init(db: Db) -> Result<(), DbErr> {
  db.exec("CREATE TABLE IF NOT EXISTS events (id TEXT PRIMARY KEY, sub TEXT NOT NULL, seq INTEGER NOT NULL, type TEXT NOT NULL, status TEXT NOT NULL)", [])?;
  db.exec("CREATE INDEX IF NOT EXISTS events_sub_seq ON events (sub, seq, status)", [])?;
  db.exec("CREATE TABLE IF NOT EXISTS subs (id TEXT PRIMARY KEY, state TEXT NOT NULL, seq INTEGER NOT NULL, history TEXT NOT NULL)", [])?;
  Ok(())
}

fn load_sub(db: Db, sub: Str) -> Result<Sub, DbErr> {
  let rows = db.query("SELECT state, seq, history FROM subs WHERE id = ?", [SqlValue::Text(sub)])?;
  if rows.len() == 0 {
    let empty: List<Str> = [];
    return Ok(Sub { exists: false, state: "none", last: 0, hist: empty });
  }
  let r = rows[0];
  Ok(Sub { exists: true, state: sv_str(r[0]), last: sv_int(r[1]), hist: parse_hist(sv_str(r[2])) })
}

fn set_status(db: Db, id: Str, st: Str) -> Result<(), DbErr> {
  db.exec("UPDATE events SET status = ? WHERE id = ?", [SqlValue::Text(st), SqlValue::Text(id)])?;
  Ok(())
}

fn process(db: Db, log: Log, ev: Event) -> Result<Resp, DbErr> {
  let claimed = db.exec("INSERT OR IGNORE INTO events (id, sub, seq, type, status) VALUES (?, ?, ?, ?, 'pending')",
    [SqlValue::Text(ev.id), SqlValue::Text(ev.sub), SqlValue::Int(ev.seq), SqlValue::Text(ev.kind)])?;
  if claimed == 0 { return Ok(status_resp(200, "duplicate")); }
  let mut first = true;
  loop {
    let s = load_sub(db, ev.sub)?;
    if ev.seq <= s.last {
      if first {
        set_status(db, ev.id, "stale")?;
        return Ok(status_resp(200, "stale"));
      }
      return Ok(status_resp(202, "queued"));
    }
    if first {
      set_status(db, ev.id, "queued")?;
      first = false;
    }
    let mut cur_last = s.last;
    let mut state = s.state;
    let mut hist = s.hist;
    let mut ids: List<Str> = [];
    let mut logs: List<Str> = [];
    let mut mine = false;
    loop {
      let want = cur_last + 1;
      let mut eid = "";
      let mut ekind = "";
      if want == ev.seq {
        eid = ev.id;
        ekind = ev.kind;
        mine = true;
      } else {
        let q = db.query("SELECT id, type FROM events WHERE sub = ? AND seq = ? AND status = 'queued' ORDER BY id LIMIT 1",
          [SqlValue::Text(ev.sub), SqlValue::Int(want)])?;
        if q.len() == 0 { break; }
        eid = sv_str(q[0][0]);
        ekind = sv_str(q[0][1]);
      }
      match next_state(state, ekind) {
        Some(ns) => { state = ns; hist.push(ns); },
        None => { logs.push("invalid transition " + eid); },
      }
      ids.push(eid);
      cur_last = want;
    }
    if ids.len() == 0 { return Ok(status_resp(202, "queued")); }
    let htext = hist_json(hist).to_json();
    let changed = if s.exists {
      db.exec("UPDATE subs SET state = ?, seq = ?, history = ? WHERE id = ? AND seq = ?",
        [SqlValue::Text(state), SqlValue::Int(cur_last), SqlValue::Text(htext), SqlValue::Text(ev.sub), SqlValue::Int(s.last)])?
    } else {
      db.exec("INSERT OR IGNORE INTO subs (id, state, seq, history) VALUES (?, ?, ?, ?)",
        [SqlValue::Text(ev.sub), SqlValue::Text(state), SqlValue::Int(cur_last), SqlValue::Text(htext)])?
    };
    if changed == 0 { continue; }
    let mut stmts: List<Str> = [];
    let mut params: List<List<SqlValue>> = [];
    for e in ids {
      stmts.push("UPDATE events SET status = 'applied' WHERE id = ?");
      params.push([SqlValue::Text(e)]);
    }
    db.transaction(stmts, params)?;
    for l in logs { logw(log, l); }
    if !mine { return Ok(status_resp(202, "queued")); }
    let mut m: Map<Str, Json> = Map::new();
    m.insert("status", Json::Str("applied"));
    m.insert("applied", Json::Num(ids.len()));
    return Ok(resp(200, Json::Obj(m).to_json()));
  }
}

fn webhook(req: Incoming, db: Db, secrets: Dir, log: Log) -> Result<Resp, DbErr> {
  let mut key = match secrets.read("webhook.key") {
    Ok(b) => b,
    Err(_) => { return Ok(resp(500, obj1("error", "internal error"))); },
  };
  if key.len() > 0 && key[key.len() - 1] == 10 { key = key.slice(0, key.len() - 1); }
  if key.len() > 0 && key[key.len() - 1] == 13 { key = key.slice(0, key.len() - 1); }
  let body = req.body();
  let names = req.header_names();
  let values = req.header_values();
  let mut sig: Option<Str> = None;
  let mut i = 0;
  while i < names.len() && i < values.len() {
    if names[i] == "x-signature" { sig = Some(values[i]); break; }
    i += 1;
  }
  let mut msg = key;
  msg.extend(".".to_bytes());
  msg.extend(body);
  let expected = "sha256=" + msg.sha256().to_hex();
  let ok = match sig { Some(s) => s.ct_eq(expected), None => false };
  if !ok {
    logw(log, "rejected signature");
    return Ok(resp(401, obj1("error", "bad signature")));
  }
  let Some(ev) = parse_event(body) else {
    return Ok(resp(400, obj1("error", "invalid event")));
  };
  init(db)?;
  process(db, log, ev)
}

fn get_sub(db: Db, id: Str) -> Result<Resp, DbErr> {
  init(db)?;
  let s = load_sub(db, id)?;
  if !s.exists || s.last < 1 { return Ok(not_found()); }
  let mut m: Map<Str, Json> = Map::new();
  m.insert("id", Json::Str(id));
  m.insert("state", Json::Str(s.state));
  m.insert("seq", Json::Num(s.last));
  m.insert("history", hist_json(s.hist));
  Ok(resp(200, Json::Obj(m).to_json()))
}

fn route(req: Incoming, db: Db, secrets: Dir, log: Log) -> Result<Resp, DbErr> {
  let target = req.target();
  let path = target.split("?")[0];
  let method = req.method();
  if path == "/webhooks" {
    if method != "POST" { return Ok(not_found()); }
    return webhook(req, db, secrets, log);
  }
  if let Some(id) = path.strip_prefix("/subscriptions/") {
    if method == "GET" && id.len() > 0 && !id.contains("/") {
      return get_sub(db, id);
    }
  }
  Ok(not_found())
}

fn main(req: Incoming, res: Outgoing, db: Db, secrets: Dir, log: Log) -> Str {
  let r = match route(req, db, secrets, log) {
    Ok(r) => r,
    Err(_) => resp(500, obj1("error", "internal error")),
  };
  match res.send(r.status, ["content-type"], ["application/json"], r.body.to_bytes()) {
    Ok(_) => r.status.to_str(),
    Err(_) => "send failed",
  }
}
